update content_bodies set title = '廣澤徳三郎工房で伊賀組紐作り体験', description = '伊賀市で人気の体験メニューである「伊賀組紐作り」と「伊賀焼陶芸体験」を行ってきました。今回はその2つの体験についてレポートします。2016年津クイーンの角谷奈津実さんがモデルとして登場しています。詳細はレポートリンクをご覧ください。' where id = 'S1S-XhgulU52RNtVRZ0M2';
update content_bodies set title = 'Experience Iga Kumihimo Weaving at Hirozawa Tokusaburo Workshop', description = 'I visited Iga City to experience two popular activities: Iga Kumihimo weaving and Iga pottery. This report covers both experiences, featuring model Natsumi Kakutani, who was crowned Miss Tsu in 2016. For more details, visit the report link.' where id = 'Q0TUAl2ZogdJKkEHv-Exd';
update content_bodies set title = 'うきは市の観光と森林セラピー', description = 'この動画では、福岡県のうきは市における観光や森林セラピーについて紹介しています。' where id = 'SLDgSCE4oj61IHcKjL8bM';
