update content_bodies set title = 'うきは天然リトリート体験＿森林ライド', description = 'うきは市の山間部で行われる「うきは天然リトリート体験・森林ライド（サイクリング）」は、サイクリング初心者から中級者向けのコースを用意しています。令和5年4月の実施に向けて、現在準備を進めています。' where id = '-on0gyc6rVR1AgIrv7nNo';
update content_bodies set title = 'Ukiha Natural Retreat Experience: Forest Ride', description = 'The ''Ukiha Natural Retreat Experience: Forest Ride (Cycling)'' is offered in the mountainous area of Ukiha City. We are preparing courses suitable for beginner to intermediate cyclists. The event is scheduled to take place in April 2023.' where id = 'kUtdtrgnA15qF1Q-aqkvg';
update content_bodies set title = 'うきは天然リトリート体験＿森林セラピー', description = 'うきは市の山間部で提供される「うきは天然リトリート体験・森林セラピー＋ヨーガ／足浴編」についての情報です。この体験は、自然の中で心身をリフレッシュさせることを目的としており、令和5年4月の実施に向けて現在準備が進められています。参加者は森林の中でのセラピーやヨーガ、足浴を通じて、リラックスした時間を過ごすことができるでしょう。' where id = 'phu_oVqTzEAXW6wu8ZrBv';
update content_bodies set title = 'Ukihara Natural Retreat Experience: Forest Therapy', description = 'The ''Ukihara Natural Retreat Experience: Forest Therapy + Yoga/Foot Bath Edition'' is offered in the mountainous area of Ukihara City. Preparations are underway for its implementation in April 2023.' where id = 'j7cveqQEGB7vxI0PZxPMb';
update content_bodies set title = 'うきは天然リトリート体験＿森林サウナ', description = 'うきは市の山間部で提供される「うきは天然リトリート体験・森林サウナ編」についての情報です。この体験は、令和5年4月の実施に向けて現在準備が進められています。自然の中でリラックスできる機会を提供し、森林の中でのサウナ体験を通じて心身のリフレッシュを図ることが目的です。' where id = '5be0tzOq0CRnxrboGdWdl';
update content_bodies set title = 'Ukihara Natural Retreat Experience: Forest Sauna', description = 'The ''Ukihara Natural Retreat Experience: Forest Sauna Edition'' is offered in the mountainous area of Ukihara City. Preparations are underway for its implementation in April 2023.' where id = 'xcps3JEz3X-19DlsRZPoF';
update content_bodies set title = 'うきは天然リトリート体験', description = 'うきは市の山間部で提供される「うきは天然リトリート体験」が、令和5年4月の実施に向けて準備中です。' where id = 'iSR1qVE6hMwsfzAd8VS0_';
