update content_bodies set title = 'うきはの今 秋バージョン', description = 'このテキストは、福岡県に位置するうきは市の秋のバージョンを紹介しています。浮羽稲荷神社や調音の滝、つづら棚田などの観光名所が挙げられています。秋の季節におけるうきはの美しさを強調し、地域の観光を促進する内容となっており、文化的および自然的なランドマークを紹介しています。' where id = 'ycndg5XJAGG8gki9Qr7jS';
update content_bodies set title = 'Autumn Version of Ukiha', description = 'This text highlights the autumn version of Ukiha, a city located in Fukuoka Prefecture, Japan. It mentions various attractions such as the Ukihainari Shrine, Chouon Falls, and Tsuzura Rice Terraces. The description emphasizes the beauty of Ukiha in the autumn season and encourages tourism in the region, showcasing its cultural and natural landmarks.' where id = 'BSt49Erba3QkqUHyfn8kC';
update content_bodies set title = '浮羽稲荷神社ライトアップアート2022', description = '2022年2月、福岡県うきは市の浮羽稲荷神社で行われたイベントの様子を紹介します。このイベントでは、神社が美しいライトアップで彩られ、訪れる人々に幻想的な雰囲気を提供しました。2022年の成功を受けて、2023年1月にも同様のイベントが開催されることが決定しました。このイベントは、うきは観光みらいづくり公社が主催し、浮羽稲荷神社奉賛会やうきは市が協力しています。' where id = 'Z3_WQgO0ftU8TUIXesBFI';
update content_bodies set title = 'Ukihainari Shrine Light-Up Art 2022', description = 'This event took place in February 2022 at Ukihainari Shrine in Ukiha City, Fukuoka Prefecture. The event featured stunning light displays that illuminated the shrine, creating a magical atmosphere for visitors. Following the success of the 2022 event, it has been announced that the Ukihainari Shrine Light-Up Art event will also be held in January 2023. The event is organized by the Ukiha Tourism Future Creation Corporation, with support from the Ukihainari Shrine Support Association and Ukiha City.' where id = 'cW6R1PGGn5lS3C-PWySMR';
update content_bodies set title = 'うきはの今 2022 夏', description = 'この文章は、福岡県うきは市のさまざまな観光名所やスポットを紹介しています。筑後川や浮羽稲荷神社、城ヶ鼻公園、調音の滝公園などが挙げられています。また、ギャラリー安政、つづら棚田、清水湧水、耳納連山についても言及されています。さらに、道の駅うきはや吉井町、白壁の町並みの美しさについても触れています。' where id = 'pmX4jpsnMiTMK4tVx3ng1';
update content_bodies set title = 'Ukiha Now: Summer 2022', description = 'This text highlights various attractions and locations in Ukiha, Fukuoka Prefecture, Japan. It mentions the Chikugo River, Ukihainari Shrine, and several parks such as Jogahina Park and Chouon Falls Park. Additionally, it references Gallery Ansei, Tsuzura Rice Terraces, Shimizu Spring, and the Minou Mountain Range. The text also includes mentions of the Ukiha Roadside Station, Yoshii Town, and the picturesque white-walled townscape.' where id = '_jDcK9W3OIRbK5auDvwaj';
