update content_bodies set title = '福岡県うきは市のよかもんいちご', description = 'この動画では、福岡県うきは市で栽培されているよかもんいちごについて紹介しています。よかもんいちごは、その甘さと風味で知られ、多くの人々に愛されています。うきは市は、いちごの生産が盛んな地域であり、地元の特産品としても人気があります。この動画を通じて、よかもんいちごの魅力を知ることができます。' where id = 'jLrIJ_THLLgklx1QiBS4i';
