update content_bodies set title = '【イベント告知】浮羽稲荷神社ライトアップアート【福岡県うきは市】', description = '福岡県うきは市の浮羽稲荷神社でライトアップイベントが開催されます。開催日は2022年2月23日（水祝）から27日（日）までで、時間は18:30から21:30です。小雨決行となっており、同時に夜市（飲食出店）も開催予定です。詳細はうきは観光みらいづくり公社のWebサイトをご覧ください。' where id = 'U7FfKkiqObTufGvLwDoCm';
update content_bodies set title = 'Event Announcement: Light-Up Art at Ukihainari Shrine in Ukiha City, Fukuoka Prefecture', description = 'A light-up event will be held at Ukihainari Shrine in Ukiha City, Fukuoka Prefecture. The event will take place from February 23 to 27, 2022, from 6:30 PM to 9:30 PM. It will proceed in light rain, and a night market featuring food stalls is also planned. For more details, please visit the Ukihalove website.' where id = '-7bRNZlHv447E2KihY3o4';
update content_bodies set title = '【うきはショートトリップ】第２回うきはオンライン体験ツアー', description = '2021年11月19日に配信された第２回うきはオンライン体験ツアーでは、「うきはショートトリップ動画 ＃新しいお店行ってみた」が紹介されました。このイベントは、コロナ禍において自宅でうきは市の魅力を体験したいというニーズに応えるために企画されました。参加者は、うきは市を巡るような体験を楽しむことができ、Genko2 STEAK HOUSE、うきは猫カフェ280、うきはせれくと、kawasemi danishなどの新しいお店を訪れる様子が収められています。イベントは、うきは観光みらいづくり公社によって運営され、うきは市の魅力を伝えることを目的としています。' where id = '9v_qTR1MkEJMWuaE0jMkK';
update content_bodies set title = 'Ukiha Short Trip: 2nd Online Experience Tour', description = 'The 2nd Ukiha Online Experience Tour was broadcast on November 19, 2021, featuring the ''Ukiha Short Trip Video: Trying New Shops.'' This event was designed to allow participants to explore Ukiha City from home during the COVID-19 pandemic, providing a virtual experience of traveling around the area. The video includes visits to various local establishments, such as Genko2 STEAK HOUSE, Ukiha Cat Cafe 280, Ukiha Select, and Kawasemi Danish. The event was organized by the Ukiha Tourism Future Creation Corporation, aiming to showcase the charm of Ukiha City.' where id = '-li6GR1CzN2itRC0ogj6b';
update content_bodies set title = '【西見柿農園】第２回うきはオンライン体験ツアー【2021年11月19日配信】', description = '2021年11月19日に配信された第2回うきはオンライン体験ツアーでは、西見柿農園の紹介動画が公開されました。この動画では、農園の特徴や柿の栽培過程についての情報が提供され、視聴者に農園の魅力を伝えています。' where id = 'WUd_L91YZ2PttSs5UO7Vr';
update content_bodies set title = 'Nishimi Persimmon Farm: 2nd Ukiha Online Experience Tour (Broadcasted on November 19, 2021)', description = 'This is an introduction video of Nishimi Persimmon Farm featured in the 2nd Ukiha Online Experience Tour, which was broadcasted on November 19, 2021. The tour showcases the farm''s offerings and provides insights into the persimmon cultivation process.' where id = 'gQxEAxmNWEKMihPik_XjE';
update content_bodies set title = '株式会社みずほファーム 第2回うきはオンライン体験ツアー', description = '2021年11月19日に配信された第2回うきはオンライン体験ツアーでは、株式会社みずほファームの紹介動画が公開されました。このツアーは、福岡県うきは市の魅力を伝えるもので、みずほファームの活動や特徴を紹介しています。' where id = '5q0Pm8WBnBsmyP3BMkdId';
update content_bodies set title = 'Mizuho Farm Co., Ltd. Second Ukiha Online Experience Tour', description = 'This is an introduction video of Mizuho Farm Co., Ltd. featured in the second Ukiha online experience tour, which was broadcast on November 19, 2021.' where id = 'ekCHdwEQPqcquKD9XC4nt';
update content_bodies set title = '第１回うきはオンライン体験ツアー', description = '2021年9月3日に配信された第１回うきはオンライン体験ツアーは、コロナ禍において自宅からうきは市の現状を覗き見たいというニーズに応えるために企画されました。このイベントの中で提供された「うきはショートトリップ」は、参加者にうきはを巡るような体験を提供することを目的としています。うきは観光みらいづくり公社が企画・運営を行い、動画は地域おこし協力隊の井上宗之輔が制作しました。詳細は公式ウェブサイトをご覧ください。' where id = 'PJImQSrJ16d-lkTb87jei';
update content_bodies set title = 'First Ukihashi Online Experience Tour', description = 'The first Ukihashi online experience tour was broadcast on September 3, 2021. This event was designed to allow participants to explore the current state of Ukihashi City from home, especially during the COVID-19 pandemic. The ''Ukihashi Short Trip'' segment of the event aimed to provide a virtual experience of traveling around Ukihashi. The tour was organized by the Ukihashi Tourism Future Creation Corporation, and the video was produced by the local revitalization cooperation team led by Munenori Inoue. For more information, you can visit the official website.' where id = 'Pd-T6nrRW6dyD_6ja5Tyf';
update content_bodies set title = 'ファゼンダかじわら株式会社 第１回うきはオンライン体験ツアー', description = '2021年9月3日に配信された第１回うきはオンライン体験ツアーにおいて、ファゼンダかじわら株式会社の紹介動画が公開されました。この動画では、同社の特徴や提供する体験について紹介されています。ファゼンダかじわらの詳細は公式ウェブサイトやInstagramで確認できます。' where id = '4FnbGQfQbhxTR8zIjEfNJ';
update content_bodies set title = 'Fazenda Kajiwara Co., Ltd. First Ukih Online Experience Tour', description = 'This is an introduction video of Fazenda Kajiwara Co., Ltd. from the first Ukih online experience tour, which was broadcasted on September 3, 2021.' where id = 'wmX490gVjlLzdtbK5veXN';
update content_bodies set title = '【堀江銘茶園】第１回うきはオンライン体験ツアー【2021年9月3日配信】', description = '2021年9月3日に配信された第１回うきはオンライン体験ツアーでは、福岡県うきは市にある堀江銘茶園が紹介されました。堀江銘茶園は明治40年に創業し、七代続くお茶農家です。詳細は公式ウェブサイトを訪れるか、InstagramやTwitterでフォローしてください。' where id = '69Bv0AqfRHosVilNLWwuM';
update content_bodies set title = 'Horie Meichaen: First Online Experience Tour of Ukiha (Broadcasted on September 3, 2021)', description = 'This is an introduction video of Horie Meichaen, a tea farm that has been operating for seven generations since its establishment in 1907, located in Ukiha City, Fukuoka Prefecture. The online experience tour was broadcasted on September 3, 2021. For more information, visit their website or follow them on Instagram and Twitter.' where id = 'hlvm9-ig-Q-yI2cLYFqc-';
