update content_bodies set title = '小岩井農場にひつじのショーンがやってきた！', description = '岩手県雫石町の観光スポット「小岩井農場まきば園」で、2025年7月1日から9月30日まで「ひつじのショーン」との特別コラボ企画が開催されます。これは、キャラクター誕生30周年を祝うもので、「ショーンと一緒なら毎日が楽しくなる」というテーマのもと、ショーンのエピソードを取り入れた様々な遊びやスポーツが楽しめる空間が演出されます。自然やアクティビティ、グルメ、お土産など、五感で楽しめる小岩井農場まきば園への来園をぜひお待ちしております。' where id = 'm7cM6eXcLW6KHkGx2IEh9';
update content_bodies set title = 'Shaun the Sheep Comes to Koiwai Farm!', description = 'From July 1 to September 30, 2025, Koiwai Farm Makiba-en in Iwate Prefecture will host a special collaboration with Shaun the Sheep, celebrating the character''s 30th anniversary. The theme for this event is ''Life’s a Treat with Shaun the Sheep,'' featuring various activities and sports inspired by episodes of the show. Visitors can enjoy a sensory experience with nature, activities, gourmet food, and souvenirs at this popular tourist spot. Don''t miss the chance to visit Koiwai Farm Makiba-en!' where id = 'fNu28PSGpKPhvVp9uMplo';
update content_bodies set title = '松阪まるよし（三重県松阪市）', description = '松阪まるよしでは、約600㎏の牛からわずか10㎏しか取れない極上ロースを使用した柔らかく甘みのある松阪牛ロースステーキを楽しむことができます。また、あっさりとした味わいを求める方のために誕生した松阪牛モモステーキも提供されています。松阪市の歴史や文化を感じながら、これらの美味しい料理を堪能することができます。' where id = 'u5MHKpXkRWmsaJ8YWf7KK';
update content_bodies set title = 'Matsusaka Maruyoshi (Matsusaka City, Mie Prefecture)', description = 'Matsusaka Maruyoshi offers exquisite Matsusaka beef steak, featuring tender and sweet meat from the prized loin, which yields only about 10 kg from a 600 kg cow. The menu includes the popular Matsusaka beef loin steak and the lighter Matsusaka beef round steak, catering to those who prefer a more delicate flavor. Visitors can enjoy these culinary delights while exploring the rich history and culture of Matsusaka City.' where id = '_J1xixD6Ijtnct6lo5NaR';
update content_bodies set title = '一度は観てみたい！三重の絶景・木津呂・英虞湾・鬼ヶ城', description = '三重県の絶景をドローン映像で紹介する動画です。熊野市の木津呂、志摩市の英虞湾、再び熊野市の鬼ヶ城が取り上げられています。動画の最後に紹介されている「詩歩の絶景トリップ」サイトは閉鎖されています。三重県の観光、旅行、イベント、宿泊情報については、公式サイト「観光三重」を訪れてください。' where id = 'QPvHR4sOYavyckZZSUnUG';
update content_bodies set title = 'Must-See Scenic Spots in Mie: Kizuro, Ago Bay, and Onigajo', description = 'This video showcases breathtaking drone footage of scenic spots in Mie Prefecture, Japan. The featured locations include Kizuro in Kumano City, Ago Bay in Shima City, and Onigajo, also in Kumano City. Note that the website ''Shipo''s Scenic Trip'' mentioned at the end of the video is no longer available. For more information on tourism, travel, events, and accommodation in Mie, visit the official Mie Prefecture tourism site ''Kankomie''.' where id = 'FJuFryoKlZpjOzG7pJrZt';
update content_bodies set title = '国見温泉　森山荘', description = '国見温泉　森山荘は、岩手県岩手郡雫石町に位置する温泉宿です。住所は〒020-0582です。予約やお問い合わせは、090-1930-2992までご連絡ください。受付時間は7:00から20:00までですが、冬季（11月中旬から5月10日頃まで）は18:00から21:00までの受付となります。この温泉はエメラルドグリーンの湯が特徴で、秋田駒ケ岳の近くにあり、湯治を求める人々にとって隠れた名所となっています。' where id = 'nBZ60VeoHMkrq5_1C4N7K';
update content_bodies set title = 'Kunimi Onsen Moriyama-so', description = 'Kunimi Onsen Moriyama-so is located in Shizukuishi Town, Iwate Prefecture, at 〒020-0582. For reservations and inquiries, you can contact them at 090-1930-2992, available from 7:00 AM to 8:00 PM. During the winter season, from mid-November to around May 10, the reception hours are from 6:00 PM to 9:00 PM. The onsen is known for its emerald green waters and is situated near Akita Komagatake, making it a hidden gem for those seeking a therapeutic hot spring experience.' where id = 'cDl-dXXeJjJJYJ1LjO2DA';
update content_bodies set title = 'スペイン村の新エンターテイメント・ストリートミュージカル☆', description = '志摩スペイン村パルケエスパーニャで、ストリートミュージカル「エンシエロ！～UNO! DOS! TRES! MOOH! ちょっと変わった牛追い祭り！～」が開催されます。このミュージカルは、スペインの伝統的な牛追い祭りをテーマにしたもので、観客に新しいエンターテイメント体験を提供します。' where id = 'TVZ9z3c2SRi-IXEiXdzah';
update content_bodies set title = 'New Entertainment Street Musical in Spain Village☆', description = 'The street musical ''Enciero! ~UNO! DOS! TRES! MOOH! A Slightly Unusual Running of the Bulls!~'' is being held at Shima Spain Village Parque Espana.' where id = 'RNZvh4Kbmzp_INwtjiZFy';
update content_bodies set title = '鈴鹿サーキット・バットのクリスタルハント「バットの探検隊団結式」', description = '鈴鹿サーキットで開催される「バットのクリスタルハント」は、冒険型のシューティングアトラクションです。この参加型イベントである「バットの探検隊団結式」では、参加者が一緒に冒険を楽しむことができます。' where id = 'uqwWQnA7LdQ2TzeKjZ3ES';
update content_bodies set title = 'Crystal Hunt at Suzuka Circuit: Bat Expedition Team Formation Ceremony', description = 'The Bat''s Crystal Hunt is an adventure-themed shooting attraction at Suzuka Circuit. This event, known as the ''Bat Expedition Team Formation Ceremony,'' invites participants to engage in an interactive experience.' where id = 'yzRSnetSDgks41lwM2Gx4';
update content_bodies set title = '鈴鹿サーキットの新アトラクション☆バットのパワークリスタルハント', description = '鈴鹿サーキットに新たに登場したアトラクション、バットのパワークリスタルハントは、冒険型のシューティングアトラクションです。参加者は、バットをテーマにした冒険の中で、パワークリスタルを探し出すという体験を楽しむことができます。' where id = 'G_J3sI0hnRsUQVrh1H43O';
update content_bodies set title = 'New Attraction at Suzuka Circuit: Bat''s Power Crystal Hunt', description = 'Bat''s Power Crystal Hunt is an adventure-based shooting attraction at Suzuka Circuit.' where id = 'yhXRbbiRqHFVBBD4QbDxE';
update content_bodies set title = '紀北のたび', description = '紀北町紀伊長島区古里では、温泉と新鮮な魚介類を存分に楽しむことができます。美しい自然に囲まれたこの地域で、リラックスしたひとときを過ごしながら、地元の美味しい海の幸を味わうことができるのが魅力です。観光三重が提供する情報を参考に、紀北の魅力を体験してみてください。' where id = 'bcy48smCenIFtOekTmP8d';
update content_bodies set title = 'Kihoku Travel', description = 'Enjoy the hot springs and seafood in the Kihonaka area of Kihoku Town!' where id = 'y97SCkAxvbhPojM5v-RV2';
update content_bodies set title = 'フラワー＆ガーデン「ホテル森の風鶯宿」', description = 'フラワー＆ガーデン「ホテル森の風鶯宿」は、岩手県岩手郡雫石町鴬宿に位置する宿泊施設です。美しい庭園に囲まれた静かな環境を提供し、温泉が楽しめることで知られています。お問い合わせは019-695-3333までどうぞ。' where id = 'moC_mYD1E4sbvOi5rfW4m';
update content_bodies set title = 'Flower & Garden ''Hotel Mori no Kaze Ushu''', description = 'Flower & Garden ''Hotel Mori no Kaze Ushu'' is located in Ushu, Shizukuishi Town, Iwate Prefecture, Japan. The hotel offers a serene environment with beautiful gardens and is known for its hot springs. For inquiries, you can contact them at 019-695-3333.' where id = 'fsVDXJPAZvuTseC4KD-2H';
update content_bodies set title = '紀和の雲海', description = '紀和の雲海は、訪れる人々を魅了する美しい景観現象です。この地域は、幻想的な雲の形成で知られており、自然愛好者や写真家にとって人気のある目的地となっています。雲が風景を包み込む光景を目の当たりにする体験は非常にユニークで、日常生活の喧騒からの静かな逃避を提供します。' where id = 'HsGs15TVon7skjmQ5dv7o';
update content_bodies set title = 'Kiwa''s Sea of Clouds', description = 'Kiwa''s Sea of Clouds is a scenic phenomenon that captivates visitors with its breathtaking views. The area is known for its stunning cloud formations that create a mystical atmosphere, making it a popular destination for nature lovers and photographers. The experience of witnessing the clouds enveloping the landscape is truly unique and offers a serene escape from the hustle and bustle of daily life.' where id = 'tFOWBONXv3pJsyVEc5vVs';
update content_bodies set title = 'あみはりロッジ', description = 'あみはりロッジは、岩手県岩手郡雫石町に位置する宿泊施設です。美しい自然に囲まれた環境で、快適な宿泊体験を提供しています。お問い合わせは019-693-2313まで、またはファックス019-693-2830にて受け付けています。住所は、〒020-0585 岩手県岩手郡雫石町長山岩手山22-289です。' where id = 'lh1GDMucghXD5Es6N2X4E';
update content_bodies set title = 'Amihari Lodge', description = 'Amihari Lodge is located in Shizukuishi Town, Iwate Prefecture, Japan. The lodge offers a cozy accommodation experience in a picturesque setting. For inquiries, you can contact them at 019-693-2313 or send a fax to 019-693-2830. The lodge is situated at 22-289 Nagayama, Iwate Mountain, Shizukuishi Town, Iwate, 020-0585.' where id = 'mVR_7qafJPnuPax2x6vsD';
update content_bodies set title = '離れのペンション・レンタルCafé クレソン', description = '離れのペンション・レンタルCafé クレソンは、岩手県岩手郡雫石町長山盆花平に位置しています。この施設は、快適な宿泊体験とレンタルカフェサービスを提供しています。お問い合わせは019-693-1755までどうぞ。周囲の美しい自然環境が魅力で、リラックスや自然を楽しむのに最適なスポットです。' where id = 'Q59wnXHxn15xnVdVIDhcR';
update content_bodies set title = 'Detached Pension & Rental Café Cresson', description = 'Detached Pension & Rental Café Cresson is located in Nagayama Bonkakei, Shizukuishi Town, Iwate Prefecture, Japan. The establishment offers a cozy accommodation experience along with a rental café service. For inquiries, you can contact them at 019-693-1755. The location is known for its beautiful surroundings, making it an ideal spot for relaxation and enjoying nature.' where id = 'WMeUE0bff8yRPOM4tMqwa';
update content_bodies set title = 'ペンション さんりんしゃ', description = 'ペンション さんりんしゃは、岩手県岩手郡雫石町に位置しています。住所は、〒020-0585 岩手県岩手郡雫石町長山岩手山22-195です。お問い合わせは、電話019-693-2311またはファックス019-693-3223で受け付けています。このペンションは、美しい自然環境の中で快適な宿泊体験を提供しています。' where id = 'tRhvlWXmxxDP50dD53JQh';
update content_bodies set title = 'Pension Sanrinsha', description = 'Pension Sanrinsha is located in Iwate Prefecture, specifically in the town of Shizukuishi. The address is 22-195 Nagayama, Iwate-yama, Shizukuishi, Iwate 020-0585. For inquiries, you can contact them via phone at 019-693-2311 or fax at 019-693-3223. This pension offers a cozy accommodation experience in a beautiful natural setting.' where id = 'T9ULMM0DCRUpE8Mc1DVIk';
update content_bodies set title = '河内渓谷の紅葉は最高！', description = '2011年11月18日、津市芸濃町にある河内渓谷へ家族でお出かけしました。紅葉が素晴らしく、もみじが真っ赤に染まっていました。観光ボランティアの方が見所などを教えてくださり、充実した時間を過ごしました。' where id = '16LVx9LEVUEh0A5AS1Fg-';
update content_bodies set title = 'The Autumn Leaves at Kawachi Valley are Amazing!', description = 'On November 18, 2011, I went on a family trip to Kawachi Valley in Geino Town, Tsu City. The autumn leaves were stunning, with the maple trees turning a brilliant red. A volunteer guide shared information about the highlights of the area.' where id = 'jg-WycCGVUOoQxbqS8KqF';
update content_bodies set title = '伊勢志摩スカイライン', description = '家族3人で伊勢志摩スカイラインにお弁当を持ってピクニックに出掛けました。展望足湯からの景色は素晴らしく、ハンモックでリラックスして過ごしました。' where id = '6-fIhmTCtLbGlHtNnaG-d';
update content_bodies set title = 'Ise-Shima Skyline', description = 'A family of three went on a picnic to the Ise-Shima Skyline, bringing along a bento. The view from the foot bath was excellent, and they enjoyed relaxing in a hammock.' where id = 'i1kCh9Hif2A5ybzLuhv0S';
update content_bodies set title = '海賊のようにピクニックを楽しもう！海の幸を使った海賊むすび', description = '「海賊むすび」の海賊ピクニックを海辺で楽しむことができます。地元の食材をふんだんに使った手作りのおにぎりセットで、価格はたったの500円です。美しいしまなみの景色を眺めながら味わってください。場所は上島の湯毛島にある「しまカフェ」で、地元の人々が作ったこのおにぎりは、まるで海賊の王様のように楽しむことができます。この特別な食体験をお見逃しなく！' where id = '51v8Aanz_SINkxkX7_-4_';
update content_bodies set title = 'Enjoy a pirate picnic with Kaizoku Musubi, onigiri inspired by the pirates of the Inland Sea!', description = 'Experience a unique Shimanami Pirate Picnic by the sea with ''Kaizoku Musubi'' onigiri sets. These delicious rice balls are made by hand using local ingredients and are available for just 500 yen. Enjoy them while taking in the beautiful views of Shimanami. Located at Shima de Cafe on Yuge Island, Kamijima, these onigiri offer a taste of the islands, allowing you to eat like a pirate king. Don''t miss out on this delightful culinary experience!' where id = 'TfgwxENwfUegv5auXty6H';
update content_bodies set title = 'ビーガン海賊？内海の海賊にインスパイアされた植物ベースの海賊むすび', description = 'ユゲ島のシマデカフェで提供される「海賊むすび」は、内海の海賊にインスパイアされたビーガンの伝統的なおにぎりです。地元の新鮮な食材を使用して手作りされたこの健康的なおにぎりは、店内での飲食やテイクアウトが可能です。島の風味を楽しみながら、地元の文化を反映した食事を堪能できます。シマデカフェでこの革新的なビーガン料理を味わってみてください。' where id = '1OhWkjWkxNSdKdUsuplAX';
update content_bodies set title = 'Vegan Pirates? Plant-based Kaizoku Musubi, onigiri inspired by the Inland Sea pirates of old!', description = 'Discover the unique ''Kaizoku Musubi'' at Shima De Cafe on Yuge Island, a vegan take on traditional onigiri inspired by the pirates of the Inland Sea. These healthy, handmade rice balls are crafted using local ingredients straight from the garden, ensuring freshness and quality. Available for dine-in or takeout, these lunches offer a delicious way to enjoy the flavors of the islands. Embrace the pirate spirit and indulge in a meal that reflects the local culture and produce. Visit Shima De Cafe for a taste of this innovative vegan cuisine.' where id = 'pxG8h3s7A1AQSh-8cSpxA';
update content_bodies set title = '海賊結び - 瀬戸内海の海賊にインスパイアされたオリジナルおにぎり！', description = '500円で、上島諸島と夢島海道から仕入れた具材を使った海賊結びおにぎり3個セットを楽しめます。具材は、岩城レモンポーク、魚島のタコとイカ、そして由岐海苔です。地元の人々が地元の食材を使って作ったこのおにぎりは、島の味を楽しむことができます。上島の由岐島にあるシマデカフェで、この海賊にインスパイアされた美味しいおにぎりを体験してください。' where id = 'VUQz-5zxYTB1Edy9boFnr';
update content_bodies set title = 'Kaizoku Musubi – Original onigiri rice balls inspired by the pirates of the Inland Sea!', description = 'For 500 yen, you can enjoy a set of three Kaizoku Musubi onigiri, featuring fillings sourced from the Kamijima Islands and Yumeshima Kaido. The fillings include Iwagi Lemon Pork, Uoshima Octopus and Squid, and Yuge Nori Laver. These onigiri are made by local people using local ingredients, offering a unique taste of the islands. Visit Shima de Cafe on Yuge Island, Kamijima, to experience this delicious pirate-inspired treat.' where id = '0xXdKRgHAixAHerQ_ysKe';
update content_bodies set title = 'しまなみシトラスパラダイス', description = 'しまなみ海道は本当にシトラスの楽園です。美味しい手作りのシトラスジャムで一日が始まりました。特にハッサク大福は絶品でした。爽やかなジュースを楽しみ、楽しいシトラスデザインの衣服を見て、地元の農家と一緒に果物を収穫しました。訪れるべき場所には、尾道島のオーベルジュユガシラとル・ミエル・ドレ、因島のしまなみビーチパーク、伊久島のカフェ・ヴィア、岩城島の岡野農園（夢島海道）があります。' where id = '9ZMPAPJHwpWqc4wNRz2S5';
update content_bodies set title = 'Shimanami Citrus Paradise', description = 'The Shimanami Kaido is a true citrus paradise, where the day began with delicious homemade citrus jams. The Hassaku daifuku was particularly delightful. Visitors can enjoy refreshing juices, explore vibrant clothing featuring fun citrus designs, and engage with friendly local farmers while picking fruit. Notable locations include Auberge Yugashira & Le Miel Doré on Omishima Island, Shimanami Beach Park on Innoshima Island, Cafe Via on Ikuchijima Island, and Okano Orchard on Iwagi Island (Yumeshima Kaido).' where id = 'ENYrln-Wj-lMMflIy_QTC';
update content_bodies set title = '民宿 雫石荘', description = '民宿 雫石荘は、岩手県岩手郡雫石町に位置する宿泊施設です。住所は、〒020-0584 岩手県岩手郡雫石町西根西篠崎33-2です。お問い合わせは、電話019-693-2739、ファックス019-693-2105で受け付けています。' where id = 'qhfIIM_BP-ci4naZGmo0x';
update content_bodies set title = 'Minpaku Shizukishi-so', description = 'Minpaku Shizukishi-so is a guesthouse located in Shizukuishi Town, Iwate Prefecture, Japan. The address is 33-2 Nishine Nishishinozaki, Shizukuishi-cho, Iwate-gun, Iwate 020-0584. For inquiries, you can contact them at TEL: 019-693-2739 or FAX: 019-693-2105.' where id = 'oUVBVM2UPz_aG9Zor2v0J';
update content_bodies set title = '温泉ペンション くまさんち', description = '温泉ペンション くまさんちは、岩手県岩手郡雫石町に位置する宿泊施設です。住所は、〒020-0585 岩手県岩手郡雫石町長山有根5-35です。お問い合わせは019-693-2027までどうぞ。くまさんちは、温泉のリラックス効果を楽しむのに最適な、落ち着いた雰囲気の宿です。' where id = 'GFs6bROBeOk0pZ4kGamzH';
update content_bodies set title = 'Kuma''s Pension', description = 'Kuma''s Pension is a hot spring accommodation located in Shizukuishi Town, Iwate Prefecture, Japan. The address is 5-35 Nagayama, Shizukuishi, Iwate, 020-0585. For inquiries, you can contact them at 019-693-2027. The pension offers a cozy atmosphere and is ideal for those looking to enjoy the relaxing benefits of hot springs in a tranquil setting.' where id = 'sKiYPPYCv566qiWPwb_KQ';
update content_bodies set title = '民宿 高見荘', description = '民宿 高見荘は、岩手県岩手郡雫石町に位置する伝統的な宿泊施設です。宿は、雫石町西根上篠崎71-1にあり、温かみのある雰囲気を提供しています。宿泊に関する問い合わせは、019-693-2736までお電話いただくか、019-693-3931にファックスを送信してください。地元のホスピタリティを体験したい旅行者にとって、静かな環境での素晴らしい選択肢です。' where id = 'z6XcluFuKR-fsTaU3b-2S';
update content_bodies set title = 'Takamisou Inn', description = 'Takamisou Inn is a traditional Japanese guesthouse located in Shizukuishi Town, Iwate Prefecture. The inn offers a cozy atmosphere and is situated at 71-1 Nishine Kamishinozaki, Shizukuishi, Iwate. For inquiries, you can contact them at 019-693-2736 or send a fax to 019-693-3931. The inn is a great choice for travelers looking to experience local hospitality in a serene environment.' where id = '7Ol7SxbTrQr41GhEFiWzF';
update content_bodies set title = '温泉民宿 栄弥', description = '温泉民宿 栄弥は、岩手県雫石町に位置する伝統的な民宿です。宿泊客は自然の温泉を楽しむことができ、リラックスしたひとときを過ごせます。詳細については、公式ウェブサイトを訪れるか、019-695-2109に直接お問い合わせください。' where id = 'qtXiB-1zGMP1VGo-Tsc7T';
update content_bodies set title = 'Sakaeya Onsen Minpaku', description = 'Sakaeya Onsen Minpaku is a traditional Japanese inn located in Shizukuishi, Iwate Prefecture. The inn offers a relaxing onsen experience, allowing guests to enjoy the natural hot springs. For more information, you can visit their website or contact them directly at 019-695-2109.' where id = 'hP1F3_IopvH9zvO9K-5q4';
update content_bodies set title = 'しまなみの人々 #ShimanamiConnect #VisitShimanami', description = '私は、島で生まれ育った住民や最近移住してきた人々と出会う機会がありました。これにより、彼らにとってこの地域が持つ重要性を深く理解することができました。地元の人々の目を通して地域を見ることで、さまざまな島々をつなぐ強いコミュニティの絆を実感しました。この体験は、他の人々にもしまなみで自分自身の物語を作ることを促しています。例えば、海町バルアメーリや生口島のカフェ・ヴィア、岩城島のしまデカフェなど、さまざまな地元のスポットを探索することができます。' where id = 'C6Yq8QGsJf-UgugjKkWW1';
update content_bodies set title = 'People of Shimanami #ShimanamiConnect #VisitShimanami', description = 'I had the opportunity to meet both long-time residents and newcomers of the islands, which enriched my understanding of the region''s importance to them. Interacting with locals allowed me to appreciate the strong sense of community that binds everyone across the islands. This experience invites others to create their own stories in Shimanami, exploring various local spots such as Umimachi Bal Ameli on Omishima Island, Cafe Via on Ikuchijima Island, and several others on Iwagi and Yuge Islands.' where id = 'n8LJGDOg6LilfeOascb0L';
update content_bodies set title = '関宿・旧街道 夜の町並み', description = '旧東海道の夜の関宿を歩いてきました。暖色で柔らかくライトアップされており、歴史を感じるとても素敵な街道でした。' where id = 'UAZxkmB4IFDkZ-4zQaEFR';
update content_bodies set title = 'Sekiyado: Nighttime Streets of the Old Highway', description = 'I walked through the old Tōkaidō highway at night in Sekiyado. The streets were softly illuminated with warm colors, creating a wonderful atmosphere that evokes a sense of history.' where id = 'lTYgScIZJ-OCQew9z4acn';
update content_bodies set title = '太陽、海、空、しまなみ海道ブルーラインの旅#ShimanamiConnect #VisitShimanami', description = '私は尾道を出発し、旅を始めることに意欲的な他のバイカーたちと共にいました。ブルーラインに沿って、曲がりくねった海岸線や素朴な村を通り抜けながら、道中の景色をゆっくり楽しみました。最終目的地の霧島に到着したのは、忘れられない夕日を見るためのちょうど良いタイミングでした。' where id = 'D-QDLT7xVj-3hYZJaO42f';
update content_bodies set title = 'Sun, seas and sky, long the Shimanami Kaido Blue Line#ShimanamiConnect #VisitShimanami', description = 'I set off from Onomichi, joining fellow bikers eager to start their adventure. Following the Blue Line, I rode along scenic coastlines and through charming villages, taking my time to appreciate the beautiful surroundings. The journey culminated at Kirosan, where I arrived just in time to witness a breathtaking sunset.' where id = 'zAp9k_n99PUq-Db3XqBRr';
update content_bodies set title = 'しまなみの味 #ShimanamiConnect #VisitShimanami', description = 'この酸味のあるレモネードは私を元気づけ、自転車の旅に備えさせてくれました。旅の途中で、エネルギーを保つための美味しい食べ物がたくさんありました。新鮮に淹れたコーヒーや甘い柑橘系のデザート、伝統的なおにぎりなど、さまざまな味を楽しみました。そして、アイスクリームなしの旅は完結しません！訪れた場所には、池内島のカフェ・ヴィア、向島のレ・ディセット・バトー、夢島海道の夕毛島のシマ・デ・カフェがありました。' where id = '2gpBjCx03b5JeKesBhFuk';
update content_bodies set title = 'Tastes of Shimanami #ShimanamiConnect #VisitShimanami', description = 'The tangy lemonade provided a refreshing boost, preparing me for my cycling adventure. Throughout my journey, I discovered a variety of delicious foods that kept my energy levels high. I savored an array of flavors, including freshly brewed coffee, sweet citrus desserts, and traditional rice balls. No trip would be complete without indulging in some ice cream! Notable stops included Cafe Via on Ikuchijima Island, Les Dix-Sept Bateaux on Mukaishima Island, and Shima De Cafe on Yuge Island (Yumeshima Kaido).' where id = 'An3UybStmhEUV9n5Ii0kl';
update content_bodies set title = 'しまなみカフェ社会 #ShimanamiConnect #VisitShimanami', description = 'しまなみエリアをサイクリングしていると、どこに行っても美味しいカフェがありました。スタイリッシュなガレットから、島のおばあさんが心を込めて作ったシンプルなおにぎりまで、各カフェは独自の料理と温かい雰囲気を提供していました。訪れるたびにカフェのオーナーの温かさを感じることができました。特に印象に残ったカフェは、向島の「Les Dix-Sept Bateaux」、夢島海道の「Shima De Cafe」、大三島の「Umimachi Bal Ameli」、生口島の「Cafe Via」です。' where id = 'AUC4Z5SEWqNkZ2obvrwIj';
update content_bodies set title = 'Shimanami Cafe Society #ShimanamiConnect #VisitShimanami', description = 'While cycling through the Shimanami area, I discovered a variety of delightful cafes, each offering unique dishes and a welcoming atmosphere. From stylish galettes to simple rice balls made with care by local grandmothers, every cafe had its own charm. The warmth and friendliness of the cafe owners made each stop a memorable experience. Notable cafes included Les Dix-Sept Bateaux on Mukaishima Island, Shima De Cafe on Yuge Island, Umimachi Bal Ameli on Omishima Island, and Cafe Via on Ikuchijima Island.' where id = 'mXQU4rjr_H2XtczUApyzh';
update content_bodies set title = 'しまなみ海道で島のスローライフを楽しもう', description = 'しまなみ海道は、日本の本州と四国を結ぶ70kmの美しい自転車ルートで、世界でもアクセスしやすい場所の一つです。このルートを通じて、瀬戸内海の島々を巡ることは、日本での忘れられない体験の一つです。レンタル自転車が豊富に用意されており、アイコニックな「ブルーライン」で明確に示されたルートに沿ってサイクリングを楽しむことができます。地元の人々との交流も訪問のハイライトであり、友好的な住民と会話を楽しむことができます。このビデオでは、ソロ旅行者がバッテリーアシスト自転車を利用して、名所を訪れたり、田舎道を探索したりする様子が紹介されています。' where id = '6_gBEdrrd62uAf61ivdu4';
update content_bodies set title = 'Connect with the slow life of island life along the Shimanami Kaido', description = 'The Shimanami Kaido is a stunning 70km bike route in Japan, connecting the islands between Honshu and Shikoku. This route is renowned for its breathtaking views and accessibility, making it a must-visit for cycling enthusiasts. Travelers can easily rent bikes from numerous terminals along the clearly marked ''Blue Line,'' allowing for a stress-free exploration of the area. Engaging with the local community is a key highlight, as visitors can meet and converse with the friendly residents of Shimanami. The video showcases a solo traveler using a battery-assisted bike to discover iconic sights and scenic country roads, emphasizing the relaxed pace of island life.' where id = '-m1t1p0n5cST2n23PUGY5';
update content_bodies set title = 'しまなみ海道のスローライフに触れる旅、パート1 尾道から瀬戸田へ', description = 'しまなみ海道は、日本で最も美しくアクセスしやすい70kmの自転車ルートです。このルートを通じて、瀬戸内海の島々を巡り、本州と四国を結ぶ名橋を渡ることができ、忘れられない体験が待っています。レンタル自転車の豊富な選択肢と、今や象徴的な「ブルーライン」で明示されたルートにより、この美しい地域を数日間かけてストレスなく安全に探索できます。また、旅の途中で地元の人々と出会い、会話を楽しむことも大きな魅力です。動画では、ソロ旅行者がバッテリーアシスト自転車を利用して、尾道から生口島の瀬戸田までのしまなみブルーラインを探索し、地元の人々と交流する様子が紹介されています。しまなみの魅力をぜひ体験してください。' where id = 'TbyciIfFdgNVjyvSE4QKt';
update content_bodies set title = 'Connect with the slow life of island life along the Shimanami Kaido, Part 1 Onomichi to Setoda', description = 'The Shimanami Kaido is a stunning 70km bike route in Japan, renowned for its scenic beauty and accessibility. This route allows travelers to hop between islands in the Seto Inland Sea, connecting Honshu and Shikoku via iconic bridges. With numerous bike rental options and clearly marked paths, exploring this picturesque region is both enjoyable and safe. A key aspect of the journey is the opportunity to interact with the local residents, enriching the experience. In a featured video, a solo traveler uses a battery-assisted bike to navigate the Shimanami Blue Line from Onomichi to Setoda, engaging with friendly locals along the way. Visitors are encouraged to experience the charm of Shimanami.' where id = 'bQuxw6oFjqSjVDQC3yqap';
update content_bodies set title = '夫婦岩', description = '初めての家族旅行で三重県の鳥羽・伊勢を訪れ、夫婦岩を見てきました。' where id = 'e_STal75tYKofe7SmpDUN';
update content_bodies set title = 'Wedded Rocks', description = 'This is a summary of a family trip to Toba and Ise in Mie Prefecture, where we visited the Wedded Rocks.' where id = 'pp429ASvTlyWB6-0S9feG';
update content_bodies set title = 'しまなみ海道のスローライフに触れる、パート2 ゆめしま海道', description = '日本の70kmにわたるしまなみ海道は、世界で最も美しくアクセスしやすい自転車ルートの一つです。このルートを通じて、瀬戸内海の島々を巡り、本州と四国を結ぶ橋を渡ることができ、忘れられない体験が待っています。レンタル自転車の豊富な選択肢と、アイコニックな「青いライン」で明示されたルートにより、この美しい地域を数日間かけてストレスなく探索できます。また、地元の人々との交流も訪問のハイライトです。この動画では、ソロ旅行者がバッテリーアシスト自転車を利用して、しまなみ海道を越えてゆめしま海道沿いの静かな上島を訪れます。しまなみの魅力に触れてみてください。' where id = 'nEZqd2k6IlqFT8KRUiO6Y';
update content_bodies set title = 'Connect with the slow life of island life along the Shimanami Kaido, Part 2 The Yumeshima Kaido', description = 'The Shimanami Kaido, a 70km bike route in Japan, is renowned for its stunning scenery and accessibility. This route allows travelers to island-hop across the Seto Inland Sea, connecting Honshu and Shikoku via iconic bridges. With numerous bike rental options and clearly marked paths, exploring this beautiful region is both enjoyable and safe. Engaging with the local community enhances the experience, making it memorable. In this video, a solo traveler uses a battery-assisted bike to venture beyond the Shimanami Kaido, discovering the tranquil islands of Kamijima along the Yumeshima Kaido. Visitors are encouraged to connect with the Shimanami experience.' where id = 'RSQ2d9Axn8BecBCSPCOti';
update content_bodies set title = 'しまなみ海道のスローライフに触れる、パート3：大三島と大島の探訪', description = 'しまなみ海道は、日本の本州と四国を結ぶ70kmの美しい自転車ルートで、瀬戸内海の島々を巡ることができます。このルートは、息をのむような景色とアクセスの良さで知られ、サイクリストにとって忘れられない体験を提供します。多くの自転車レンタルオプションと明確に示された道があり、この美しい地域を探索するのは楽しく安全です。地元の人々との交流も旅の魅力の一つです。このビデオでは、ソロ旅行者がバッテリーアシスト自転車を利用してメインルートを外れ、大三島の美しさを発見し、日本の中でも特に素晴らしい景色で旅を締めくくります。訪問者はしまなみの体験に触れることをお勧めします。' where id = 'lV2_VFyxzlHYfmqRK86Bl';
update content_bodies set title = 'Connect with the slow life of island life along Shimanami Kaido, Part 3 Exploring Omishima & Oshima', description = 'The Shimanami Kaido is a stunning 70km bike route in Japan, connecting Honshu and Shikoku through beautiful islands in the Seto Inland Sea. This route is renowned for its breathtaking views and accessibility, making it a memorable experience for cyclists. With numerous bike rental options and clearly marked paths, exploring this picturesque region is both enjoyable and safe. Interacting with the local residents adds a personal touch to the journey. In this video, a solo traveler uses a battery-assisted bike to venture off the main path and discover the beauty of Omishima, culminating her trip with one of Japan''s most spectacular views. Visitors are encouraged to connect with the Shimanami experience.' where id = 'b_eZxIkNyxaAJ1nFHLmct';
update content_bodies set title = '橋でつながり、人とつながる。', description = 'しまなみ海道に住む人々が、訪れる人々にその魅力を語りかける動画です。それぞれのメッセージには、彼らの想いが込められており、穏やかに流れる時間のように、しっかりと心に響きます。この動画を通じて、視聴者がしまなみ海道に行ってみたいと思うような魅力を伝えることを目指しています。地域のコミュニティとその穏やかなライフスタイルを捉え、訪問者との深いつながりを促す内容となっています。' where id = 'SqIIN8LRbOd2_nFgWW2Pq';
update content_bodies set title = 'Connect with the Slow Cycle of Island Life', description = 'This video invites viewers to experience the charm of the Shimanami Kaido through the voices of its residents. Each person''s message is infused with their feelings, conveying a sense of calm that flows like the slow passage of time. The aim is to inspire viewers to visit Shimanami Kaido, making it a compelling invitation to explore the beauty of island life. The video captures the essence of the local community and its serene lifestyle, encouraging a deeper connection with the area.' where id = 'uzMw3Q93gMLKZNrVIhUMC';
update content_bodies set title = 'アカトンボふる里さがし大作戦！', description = '御在所岳でアカトンボふる里さがし大作戦に参加しました。日差しはありましたが、風が心地よく木陰は爽やかでした。前日の風の影響でトンボの数は少なかったものの、子供たちは元気に走り回り、9匹のトンボを捕まえて「Ｇ」マークを付けることができました。楽しい夏の思い出となりました。' where id = 'BF7acg6QhjZb0Tg4KVrxs';
update content_bodies set title = 'Akatonbo Habitat Search Operation!', description = 'I participated in the Akatonbo Habitat Search Operation at Mount Gozaisho. Although it was sunny, the breeze made the shaded areas very refreshing. Due to the wind from the previous day, there were fewer dragonflies than usual. However, the children ran around and managed to catch nine dragonflies, marking them with a ''G'' symbol. It became a fun summer memory.' where id = '8s5WfPrOOcZ1pdRdRDQfM';
update content_bodies set title = '橋でつながり、人とつながる。（上島バージョン）', description = 'ゆめしま海道に住む人々が、訪れる人々にその魅力を語りかける動画です。それぞれのメッセージには、住民の想いが込められており、穏やかな時間の流れの中でしっかりと伝わります。この動画を通じて、視聴者がゆめしま海道に行ってみたいと思うような内容に仕上がっています。地域の魅力と生活のリズムを感じられる作品です。' where id = 'shXfRJ1LsRN4xI02LgLaC';
update content_bodies set title = 'Connect with the Slow Cycle of Island Life', description = 'This video invites viewers to experience the charm of Yumeshima Kaido through the voices of its residents. Each message reflects the unique thoughts and feelings of the people living there, conveying a sense of calmness akin to the slow passage of time. The aim is to inspire viewers to visit Yumeshima Kaido, making it a compelling invitation to explore the island''s beauty and lifestyle. The video captures the essence of the community and its connection to the island''s rhythm.' where id = 'KbjTUPWIox12lDGeNwHRf';
update content_bodies set title = '志摩スペイン村～アトラクション・パレード・花火～', description = '志摩スペイン村を訪れました。キャラクターやダンサーと一緒にパレードに参加できるのが楽しいですね。２日間たっぷりとパルケエスパーニャを満喫しました。' where id = 'xJpnLOnZHz02zGX3fbdJU';
update content_bodies set title = 'Shima Spain Village - Attractions, Parades, and Fireworks', description = 'I visited Shima Spain Village. It was enjoyable to participate in the parade with characters and dancers. I fully enjoyed Parque Espana over two days.' where id = 'WGodeo3Wc3hzw8R2eDXXr';
update content_bodies set title = '滝つぼでサウナ✨テントサウナの聖地', description = '「テントサウナの聖地」として注目を集めるこのキャンプ場は、高さ30ｍ、幅12ｍの美しい滝が敷地内にあります。滝の前には3種類のテントサウナが設置されており、サウナで温まった後は、滝つぼで水風呂を楽しむことができます。サウナーにとって必見のスポットです。施設内にはテントサイトやコテージ、バーベキュー棟も完備されており、コテージは冷暖房が整っているため、四季を通じて快適にキャンプが楽しめます。三重県南牟婁郡紀宝町に位置し、熊野尾鷲道路から車で約50分のアクセスが可能で、駐車場は50台分用意されています。支払いはカードや電子マネーが利用できます。' where id = 'cKeYhgkmrVXqUiFlZOtw0';
update content_bodies set title = 'Sauna at the Waterfall: A Tent Sauna Sanctuary', description = 'This unique campsite features a stunning 30-meter high and 12-meter wide waterfall, making it a popular destination known as the ''Tent Sauna Sanctuary.'' In front of the waterfall, there are three types of tent saunas available. After enjoying the warmth of the sauna, visitors can take a refreshing dip in the waterfall''s plunge pool, making it a must-visit spot for sauna enthusiasts. The facility also offers tent sites, cottages, and barbecue areas. The cottages are equipped with heating and cooling, allowing for enjoyable camping year-round. Located in Mie Prefecture, the campsite is accessible by car and has parking for 50 vehicles. Payment methods include cards and electronic money.' where id = 'QQq9woC3fJn_HfKk1L7tV';
update content_bodies set title = '伊賀茶を扱う老舗茶屋の贅沢抹茶パフェ🌟🍧', description = '伊賀の老舗茶屋で提供される贅沢な抹茶パフェは、非常に美味しいと評判です。この甘味処は多くのメディアに取り上げられ、忍者をテーマにしたパフェやドリンクが人気です。特に「忍者パフェ」は高級抹茶を贅沢に使用しており、ボリュームも満点で絶品です。また、看板猫の「茶々」に出会えるとラッキーですが、訪問時には残念ながら不在でした。むらい萬香園は三重県伊賀市に位置し、営業時間は9:00から19:30（カフェは10:00から19:00）で、木曜日が定休日です。駐車場も完備されており、伊賀鉄道「上野市駅」から徒歩約5分の距離です。' where id = 'sprg8Ahctkl7tFnx-laz0';
update content_bodies set title = 'Luxurious Matcha Parfait at a Long-established Iga Tea Shop 🌟🍧', description = 'The luxurious matcha parfait at a long-established tea shop in Iga is incredibly delicious! This popular sweet shop, featured in numerous media outlets, offers parfaits and drinks inspired by ninjas. Among their offerings, the ''Ninja Parfait'' stands out for its generous use of high-quality matcha and is both filling and delightful. Visitors are also lucky to meet the shop''s mascot cat, ''Chacha,'' although it was unfortunately absent during my visit. The shop is located at Muraibankouen in Iga City, Mie Prefecture, and is open from 9:00 AM to 7:30 PM, with the café operating from 10:00 AM to 7:00 PM. Closed on Thursdays, the shop has parking available and is about a 5-minute walk from Ueno City Station on the Iga Railway.' where id = 'Db-vPbukj37fh7s7b-4uI';
update content_bodies set title = '日本の最高のサイクリングルートであるしまなみ海道を自転車で探検', description = 'しまなみ海道は、日本の最高のサイクリングルートとして知られ、多くの「世界のベストバイクライド」リストに登場します。この70kmの島々を結ぶルートは、瀬戸内海を横断し、驚くべき橋を通り抜ける美しい景色が広がっています。優れたサイクリングインフラと手頃な価格のレンタル自転車システムが整っており、日本の「柑橘類の島々」を自転車で体験するには最適です。熱心なサイクリストでも初心者でも、しまなみ海道は日本旅行の中で最も思い出に残る部分となるでしょう。' where id = 'Iy1LAtchCOqjp0-s_M56b';
update content_bodies set title = 'Explore Japan’s Inland Sea by bike on Japan’s best cycle route | Shimanami KaidoMobile', description = 'The Shimanami Kaido is recognized as Japan''s premier cycling route, frequently featured in lists of the world''s best bike rides. This 70 km route connects several islands in the Seto Inland Sea, showcasing breathtaking bridges and stunning scenery. With excellent cycling infrastructure and an affordable bike rental system, it offers an ideal way to explore Japan''s ''citrus islands.'' Whether you''re an experienced cyclist or a novice, riding the Shimanami Kaido promises to be a highlight of your visit to Japan.' where id = '6Vg6OLIGNh6cvLBe7UpvI';
update content_bodies set title = '日本の最高のサイクリングルートであるしまなみ海道を自転車で探検', description = 'しまなみ海道は、日本の最高のサイクリングルートとして知られ、多くの「世界のベストバイクライド」リストに登場します。この70kmの島々を結ぶルートは、瀬戸内海を横断し、見事な橋を通り抜ける絶景が広がっています。優れたサイクリングインフラと手頃なレンタサイクルシステムが整っており、日本の「柑橘類の島々」を自転車で体験するには最適です。熱心なサイクリストでも初心者でも、しまなみ海道は日本旅行の中で最も思い出に残る部分となることでしょう。' where id = 'G_6t9D3prLofUXXxbI8qs';
update content_bodies set title = 'Explore Japan’s Inland Sea by bike on Japan’s best cycle route | Shimanami Kaido', description = 'The Shimanami Kaido is recognized as Japan''s premier cycling route, frequently featured in lists of the world''s best bike rides. This 70 km route connects islands across the Seto Inland Sea, showcasing breathtaking bridges and stunning scenery. With excellent cycling infrastructure and an affordable bike rental system, it offers an ideal way to explore Japan''s ''citrus islands.'' Whether you''re an experienced cyclist or a novice, riding the Shimanami Kaido promises to be a highlight of your visit to Japan.' where id = 'P06d7U6tkxyQAHY7bdTIz';
update content_bodies set title = '日本のしまなみ海道での最大のサイクリングイベント', description = 'しまなみ海道は70kmの長さを持ち、世界で最も美しくアクセスしやすいサイクリングルートの一つです。CYCLING SHIMANAMIイベントは、サイクリングの真の祭典であり、約7,000人のライダーが日本国内外から集まり、アイコニックなルートをエクスプレスウェイで走る貴重な機会を楽しみます。2022年には4年ぶりに開催され、晴れ渡る青空の下で行われ、サイクリングに最適な条件が整いました。島々の美しい景色が楽しめるこのイベントは、地元のホスピタリティとリラックスした雰囲気を提供します。この短編映画が、しまなみ海道や夢島海道でのサイクリングアドベンチャーを計画するきっかけとなることを願っています。' where id = 'WrybqIBB_IVOFBSa4Up33';
update content_bodies set title = 'The biggest cycling event on Japan’s Shimanami Kaido', description = 'The Shimanami Kaido, a 70km cycling route in Japan, is renowned for its beauty and accessibility, making it a year-round destination for cyclists. The CYCLING SHIMANAMI event is a major cycling festival that attracts around 7,000 participants from Japan and beyond, offering a unique chance to ride this iconic route on the expressway. In 2022, the event resumed after a four-year break, featuring perfect weather conditions for cycling. The stunning views of the islands enhance the experience, and the event promotes local hospitality and a relaxed atmosphere. This short film aims to inspire viewers to plan their own cycling adventures on the Shimanami Kaido and Yumeshima Kaido, with hopes of welcoming more cyclists to the region.' where id = 'Y8FCJ6HZWG34f10yjdL_o';
update content_bodies set title = 'なばなの里～シロモチくんといっしょ～', description = 'シロモチくんと一緒に、なばなの里を訪れました。そこはとても美しく、まるで夢の世界のようでした。' where id = 'QA7TX_jMml-5T8Q4Ob_VJ';
update content_bodies set title = 'Nabana no Sato - Together with Shiromochi-kun', description = 'I visited Nabana no Sato with Shiromochi-kun. It was beautiful! It felt like a dream world.' where id = '_BjWlOX9GUCJWyr6nlHij';
update content_bodies set title = 'テスト放送 - しまなみ海道とその先を二輪クルーズで', description = 'これは、しまなみ海道とその先を二輪クルーズで走ることに関するトークショーイベントのテストです。イベントは日本時間の3月12日土曜日午後4時（GMT+8）に行われます。' where id = '3D5p6B_Rfz7dV9pvnlAcF';
update content_bodies set title = 'Test Broadcast - Shimanami Kaido and Beyond with Two Wheel Cruise', description = 'This is a test for our talkshow event about riding the Shimanami Kaido and Beyond with Two Wheel Cruise on Saturday 3/12 4pm Japan Time (GMT+8).' where id = 'qYWtq_SPX0qZcKWu_z_J7';
update content_bodies set title = '電車が動いた！', description = '家族で塩浜の近鉄鉄道イベントに参加しました。電車の下を見たり、操縦を体験したりして、とても楽しかったです。綱引きの際には、なんと電車が動きました！' where id = 'SqdX6rqK0vIYIbgEsnlkh';
update content_bodies set title = 'The Train Moved!', description = 'We attended a Kintetsu railway event in Shiohama with our family. It was fun to look under the train and even try operating it. During a tug-of-war, the train actually moved!' where id = 'CH5nxmlv0B6XoNhv1u-I4';
update content_bodies set title = 'しまなみサイクリング安全ガイド', description = 'この動画では、しまなみサイクリング安全ガイドを紹介しています。サイクリストがしまなみ地域を安全に走行するための重要な安全対策やガイドラインに焦点を当てています。' where id = 'PB9NxQmf1U5AWS9AOL7Qb';
update content_bodies set title = 'Shimanami Cycling Safety Guide', description = 'This video provides an introduction to the Shimanami Cycling Safety Guide, focusing on essential safety tips and guidelines for cyclists navigating the Shimanami area.' where id = 'wHEdKAVuq-pa4G5w8SC3i';
update content_bodies set title = '【広島・尾道・フォトウェディング】2人のはじまりを素敵な思い出に！尾道フォトウェディングプラン', description = '尾道フォトウェディングプランは、広島の美しい尾道の風景の中で、カップルが特別な瞬間を捉える機会を提供します。このサービスは、しまなみジャパンの一環であり、地域に関するさまざまな体験や情報を提供しています。詳細については、公式サイトを訪れるか、Twitter、Instagram、Facebookの公式SNSアカウントをフォローしてください。' where id = '3nim4j8jdQoBlXpVY4SyT';
update content_bodies set title = 'Onomichi Photo Wedding Plan: Create Beautiful Memories of Your Beginning', description = 'The Onomichi Photo Wedding Plan offers couples a chance to capture their special moments in the picturesque setting of Onomichi, Hiroshima. This service is part of Shimanami Japan, which provides various experiences and information about the region. For more details, visit the official website or follow their social media accounts on Twitter, Instagram, and Facebook.' where id = 'DRPJb4SF2IY5gS3xNysvE';
update content_bodies set title = '搾乳体験ワクワクだー', description = '四日市市市ふれあい牧場の「春のワクワクふれあいまつり」に行ってきました。初めての乳しぼりは、ワクワクしつつも、ちょっとドキドキしていました。おじさんに丁寧に教えてもらい、上手にできました！きなこちゃん（牛の名前）ありがとう！！楽しい1日でした。' where id = 'CNx6AHGrDcnqGc84j7cHD';
update content_bodies set title = 'Exciting Milking Experience', description = 'I visited the ''Spring Exciting Interaction Festival'' at Yokkaichi City Fureai Farm. It was my first time milking a cow, and I felt both excited and a bit nervous. An instructor kindly taught me how to do it, and I managed to do it well! Thank you, Kinako-chan (the cow''s name)! It was a fun day.' where id = 'jYgoPN3XDzIVL6Tcvi2tM';
update content_bodies set title = '恋のしまなみブルーライン', description = 'この動画は恋のしまなみブルーラインについて紹介しています。' where id = 'B69V6RoqDeJiAXuoLRpTG';
update content_bodies set title = 'Love''s Shimanami Blue Line', description = 'This video introduces the Love''s Shimanami Blue Line.' where id = 'z0RRDiQnYSq6cag06Rwus';
update content_bodies set title = '伊賀上野NINJAフェスタで忍者に変身', description = '伊賀上野NINJAフェスタ2012に参加しました。忍者衣装を借りて忍者に変身し、伊賀上野城や忍者屋敷、忍者ショーを楽しみました。平日にもかかわらず、街中にたくさんの忍者がいて驚きました。' where id = 'sbLvJlu3H0ksIrWnMyy3s';
update content_bodies set title = 'Transform into a Ninja at Iga Ueno NINJA Festival', description = 'I visited the Iga Ueno NINJA Festival 2012. I borrowed a ninja costume and transformed into a ninja, enjoying Iga Ueno Castle, a ninja house, and a ninja show. I was surprised to see so many ninjas in the city even on a weekday.' where id = 'Ro90LCyOCz8RMq3GoRgoq';
update content_bodies set title = '【若柳地織】100年、ともに歩む', description = '若柳地織は、仙台・宮城のてしごととして100年の歴史を持ち、決して止まることのない織り機のリズムを体現しています。織りの過程は、空気をまとうように、やさしさを織り込むように、ゆっくりと進められています。この唯一の織元は、伝統と品質に対する強い信念を持ち、その工芸を大切にしています。' where id = 'HZ6b0cC_73byolHBCaXsC';
update content_bodies set title = 'Wakayanagi Weaving: Walking Together for 100 Years', description = 'Wakayanagi Weaving has been a part of Sendai and Miyagi''s craftsmanship for 100 years, embodying a rhythm that has never stopped. The weaving process is described as slow and gentle, akin to wrapping oneself in the air and weaving kindness into the fabric. This unique weaving company holds a strong belief in its craft, reflecting a commitment to tradition and quality.' where id = 'YmJ-fFWDe2y7PowsJDb5N';
update content_bodies set title = '【堤人形】一筆一筆に生涯を捧げる。', description = '鳥の声と葉擦れの音が響く静かな工房で、すべての工程を一人でこなす職人の姿があります。堤人形は、繊細な線や可憐な佇まい、鮮やかな色彩が特徴で、愛らしい人形には職人の揺るぎない思いが秘められています。この人形は、職人の献身と技術を反映した独自の工芸品です。' where id = 'KJG3cOGgzvu7T6ukFy6e_';
update content_bodies set title = 'Tsutsumi Dolls: A Lifetime Devoted to Each Brushstroke', description = 'In a quiet workshop where only the sounds of birds and rustling leaves can be heard, a craftsman diligently handles every step of the doll-making process alone. The dolls are characterized by delicate lines, charming postures, and vibrant colors, embodying unwavering emotions. Tsutsumi Dolls represent a unique craftsmanship that reflects the dedication and artistry of the creator.' where id = 'OzEoa5IBQ5AJlRObfRLVI';
update content_bodies set title = '【こけし】 花のように。音楽のように。', description = '仙台・宮城のてしごとたちのイベントでは、心を癒し、場を和ませるこけしが紹介されます。二人の木地師によって生み出されたこけしと、宮城県在住の音楽家・次松大助氏によるピアノ曲が共演し、手から生まれる美しさと温もりを表現します。こけしは愛される存在であり、音楽とともにその魅力を引き立てます。' where id = '9Kc5kv8cOxdDIOwvO8AEh';
update content_bodies set title = 'Kokeshi: Like Flowers, Like Music | Crafts of Sendai and Miyagi', description = 'This event showcases the beauty and warmth of kokeshi dolls, created by two artisans, alongside piano music performed by Daisuke Tsugimatsu, a musician based in Miyagi Prefecture. The kokeshi dolls are designed to heal the heart and create a soothing atmosphere, embodying love and care. The collaboration between the artisans and the musician highlights the artistic connection between handcrafted items and music, both emerging from skilled hands.' where id = '5VF-FnGz41WqxHczWoTVg';
update content_bodies set title = '【堤焼】 豊かな山野、その中で。', description = '堤焼は、仙台・宮城の伝統的な陶器で、地元の土を使用して作られています。美しい緑の森と野鳥が羽を休める湖沼のほとりという静かな環境が、この工芸の背景となっています。陶工たちはろくろを使って土を巧みに形作り、素朴で健やかな器を生み出します。この芸術は、自然と工芸が調和して共存する場所で息づいています。' where id = 'WF6oheik-IYDo2SL9VPQ7';
update content_bodies set title = 'Tsutsumi-yaki: In the Rich Mountains and Fields', description = 'Tsutsumi-yaki is a traditional pottery from Sendai, Miyagi, created using local clay. The serene environment, characterized by lush forests and lakes where birds rest, serves as the backdrop for this craft. Potters skillfully shape the clay on a potter''s wheel, producing simple yet healthy vessels that embody the essence of tradition. This art form thrives in a place where nature and craftsmanship coexist harmoniously.' where id = 'gEe8llqGR9hXx4YOysWw-';
update content_bodies set title = '【仙台箪笥】 箪笥一棹にこもる技と心。', description = '仙台箪笥は、木、鉄、漆の知識が融合した伝統的な箪笥です。職人たちの手技が受け継がれ、真摯な眼差しと息遣いが感じられる一棹一棹が、彼らの情熱を物語っています。仙台箪笥は、職人の技と心が詰まった作品であり、彼らの芸術性を証明するものです。' where id = 'FOjlLGOqGhjeJiQI4APkB';
update content_bodies set title = 'Sendai Tansu: The Craft and Spirit Encapsulated in a Single Chest', description = 'Sendai Tansu represents a unique blend of craftsmanship, where knowledge of wood, iron, and lacquer come together. This traditional chest is shaped through the meticulous skills passed down among artisans, reflecting their dedication and passion. The essence of the craftsmen''s focused gaze and breath can be felt in every piece, making each chest a testament to their artistry.' where id = '0-_-mCyU5PlhPc7rj5joU';
update content_bodies set title = '仙台・宮城のてしごとたち　手とてとテ　pv', description = '仙台・宮城には、歴史や気候風土に根ざした素晴らしい工芸品が数多く存在します。手しごとから生まれたこれらの工芸品は、私たちの生活を明るく豊かにしてくれることでしょう。『手とてとテ』は、工芸品の過去と未来を知り、新たな魅力を発見できるウェブサイトであり、作り手とあなたをつなぎます。手から手へと受け継がれる、温かみのある工芸品が私たちの手に届くまでのプロセスが、より楽しいものになることを願っています。' where id = 'DvJmxY6iROTau_bCHOyyX';
update content_bodies set title = 'Crafts of Sendai and Miyagi - Te to Te to Te PV', description = 'Sendai and Miyagi are home to many wonderful crafts shaped by their history and climate. These handmade crafts are sure to brighten and enrich our lives. ''Te to Te to Te'' is a website that connects you with artisans, allowing you to learn about the past and future of these crafts and discover their new charms. The process of bringing warm, handmade crafts from the artisan''s hands to yours is made more enjoyable.' where id = 'ave7g5Kuo6lOEH9ALtmmO';
update content_bodies set title = '伊達武将隊がお伝えする、仙台観光おすすめ情報＆冬の仙台いいものフェア', description = '仙台の観光に関するおすすめ情報と、仙台観光国際協会のオンラインショップ「伊達な銘品横丁」で開催される「冬の仙台いいものフェア」について、伊達武将隊が紹介します。このフェアは令和3年12月1日から令和4年1月16日まで行われ、干支やクリスマスなどの季節商品が販売されます。また、令和3年12月15日から19日にはJR仙台駅で現地販売会も開催されるので、ぜひ足を運んでみてください。' where id = 'DXHYI5o58nT5f-zaQ1jL5';
update content_bodies set title = 'Recommended Information for Sendai Tourism by Date Warriors & Winter Sendai Good Things Fair', description = 'The Date Warriors present recommended information for tourism in Sendai and details about the ''Winter Sendai Good Things Fair'' held from December 1, 2021, to January 16, 2022, at the Sendai Tourism International Association''s online shop ''Date''s Specialty Alley.'' Seasonal products related to the zodiac and Christmas will be available. Additionally, a local sales event will take place at JR Sendai Station from December 15 to 19, 2021, and everyone is encouraged to attend.' where id = '6n4d15oNycL0LNZpEs9e-';
update content_bodies set title = '空ノ里（四国，徳島）', description = '空ノ里は、徳島県の西阿波・剣山・吉野川観光地域に位置する高地で、夜空に螢火蟲が星のように輝く美しい場所です。この地域は自然、歴史、文化、伝説、独特の食文化が融合した日本の主要な観光地の一つです。25年の歴史を持ち、190の民宿があり、最大400人を収容可能です。多くの教育的な民宿は山の斜面にあり、独特の文化的景観を形成しています。山地や伝統的な家屋などの原風景は桃原郷とも呼ばれています。学生たちは家族の一員として迎えられ、茶や玉ねぎ、土壌ミレットなどの持続可能な農業に従事します。収穫した新鮮な野菜を使って一緒に料理をし、心の交流を深める家庭の食事を楽しみます。訪問者は、厳しい生活を豊かな生活に変える方法を学びます。' where id = 'pwMrdVhcSrK6-93LDrvCB';
update content_bodies set title = 'Sora-no-sato (Shikoku, Tokushima)', description = 'Sora-no-sato, located in the Nishiawa-Tsurugisan-Yoshinogawa tourist area of Tokushima Prefecture, is a high-altitude region known for its stunning night skies where fireflies shine like stars. This leading tourist destination in Japan boasts a rich blend of nature, history, culture, legends, and unique culinary traditions. With 25 years of history, it offers 190 private accommodations that can host up to 400 guests. Many educational guesthouses are situated in hillside villages, creating a unique cultural landscape. The area features original Japanese scenery, including mountains and traditional houses, often referred to as Momohara. Students are welcomed as family members and engage in sustainable agriculture, harvesting seasonal vegetables like tea, onions, and millet. Together, they cook rural dishes using fresh produce, fostering heartfelt connections during family meals. Visitors learn how to transform a challenging lifestyle into a prosperous one.' where id = 'TRRUOZL8jhnx8OUp6Q2bT';
update content_bodies set title = 'にし阿波 WORK CAMP－SDGｓ×キャリア教育－（2023.8.22-23）', description = '世界農業遺産の暮らしが継承される「にし阿波・そらの郷」で、真に豊かな暮らしとは何かを考えます。この地で働く素敵な大人たちとの出会いを通じて、大人の本音やリアルな社会に触れる旅です。自分らしい未来を創造するための一歩を踏み出すきっかけをつかむことができます。' where id = 'gw-0MbvgGVKwniDj1jiym';
update content_bodies set title = 'Nishi-Awa WORK CAMP - SDGs x Career Education - (August 22-23, 2023)', description = 'In the ''Nishi-Awa Sora no Sato'', where the lifestyle of the World Agricultural Heritage is preserved, participants will explore what it truly means to live richly. This journey offers encounters with wonderful adults working in the area, providing insights into their genuine thoughts and the realities of society. It serves as an opportunity to take a step towards creating a future that reflects one''s true self.' where id = 'B1IAlzFs5qHJP904IUT3S';
update content_bodies set title = 'にし阿波 WORK CAMP －SDGｓ×キャリア教育－(2023.7.27-7.28)', description = '世界農業遺産が継承される「にし阿波・そらの郷」で、真に豊かな暮らしとは何かを考えます。この地で働く素敵な大人たちとの出会いを通じて、彼らの本音やリアルな社会に触れることができる旅です。自分らしい未来を創造するための一歩を踏み出すきっかけをつかむことが目的です。' where id = '95N9DQlqTHGGRj-SnpwiZ';
update content_bodies set title = 'Nishi-Awa WORK CAMP - SDGs x Career Education - (July 27-28, 2023)', description = 'In the ''Nishi-Awa Sora no Sato'', where the lifestyle of the World Agricultural Heritage is preserved, participants will explore what it truly means to live richly. This journey offers encounters with wonderful adults working in the area, providing insights into their genuine thoughts and the realities of society. It serves as an opportunity to take a step towards creating a future that reflects one''s true self.' where id = 'mxxY3WctVt49XhLLQn7r5';
update content_bodies set title = 'ぼたんまつり', description = 'ぼたんを見にいなべへ行ってきました。ぼたんはとてもきれいでした。大きな公園にはパターゴルフもあり、楽しむことができました。' where id = 'Oesu1xYpbyGrbKWZZ7A0S';
update content_bodies set title = 'Peony Festival', description = 'I visited Inabe to see the peonies. They were beautiful. The large park also had a mini-golf course.' where id = 'MhRFQjB5wUWdOa6lWkNw7';
update content_bodies set title = '馬越峠', description = '熊野古道の馬越峠を歩きました。新緑の中でウグイスの鳴き声が響いており、自然の美しさを感じることができました。' where id = '1z3q0k3BZtShSGf16Iwfh';
update content_bodies set title = 'Umakoji Pass', description = 'I walked the Umakoji Pass on the Kumano Kodo. The sound of Japanese bush warblers resonates amidst the fresh greenery.' where id = '_jv-dc5H3coHwZuSs-Ajo';
update content_bodies set title = '東京ディズニーランドでできないことがさらにある', description = 'この記事では、東京ディズニーランドでの追加の制限について説明し、訪問者が行えないアクティビティを強調しています。詳細な理解のために、読者はウェブサイトを訪れて、より深い記事を読むことが推奨されています。また、旅行ガイド、チケット購入オプション、オンラインでのグッズ購入方法に関する便利なリンクも提供されています。著者のクリス（TDRExplorer）は、テーマパークの体験を共有し、特に東京ディズニーランドやユニバーサル・スタジオ・ジャパンなど、アジアのテーマパークを訪れるファンのためのリソースを作成しています。' where id = 'm_yqY3daZ-mAqGI7A5v00';
update content_bodies set title = 'MORE Things CAN''T Do at Tokyo Disneyland', description = 'This article discusses additional restrictions at Tokyo Disneyland, highlighting activities that visitors cannot engage in. For a more comprehensive understanding, readers are encouraged to visit the website for an in-depth article. The site also offers useful links, including a travel guide, ticket purchasing options, and information on how to buy merchandise online. The author, Chris, also known as TDRExplorer, shares his theme park experiences and has created a resource for fans of theme parks, particularly those visiting locations in Asia like Tokyo Disneyland and Universal Studios Japan.' where id = 'ZWrZNxLV5HfLcXRtfwr4T';
update content_bodies set title = '民泊体験', description = '四国、徳島県の西部に位置する「そらの郷」は、四国の中央にあるにし阿波エリア（美馬市、三好市、つるぎ町、東みよし町）にあります。そらの郷山里物語では、教育旅行としての民泊を推奨しています。生徒たちは家族の一員として迎えられ、茶摘みやタマネギ、ジャガイモ、雑穀の収穫など、少量多品目の自給的農業に参加します。収穫した旬の野菜や山菜を使って共同で田舎料理を調理し、家族団らんの食事を通じて心の交流を深め、自然に触れる体験を行います。' where id = 'c72UMZktCUMhaixsH-vkK';
update content_bodies set title = 'Minpaku Experience', description = 'Located in the western part of Tokushima Prefecture, ''Sora no Sato'' is situated in the central region of Shikoku, known as Nishi-Awa (comprising Mima City, Miyoshi City, Tsurugi Town, and Higashi-Miyoshi Town). Sora no Sato Yamazato Monogatari promotes educational travel through minpaku (private lodging). Students are welcomed as family members and engage in collaborative, small-scale, diverse agricultural activities such as tea picking and harvesting onions, potatoes, and grains. They also participate in communal cooking using seasonal vegetables and mountain herbs, fostering emotional connections during family-style meals and experiencing nature.' where id = 'ky-NUj28O6aIVL723bKFc';
update content_bodies set title = 'みまから一味(Local Food Project 徳島県)', description = '「みまから一味」は、みまから唐辛子を完熟した時期に収穫し、乾燥後に一本ずつ丁寧に拭き取り、雑味を取り除きます。その後、一定量ずつ焙煎し、繊維を壊さないようにゆっくりと石臼で挽きます。このようにして作られた逸品は、旬の味にこだわり、フレッシュで風味豊かです。激辛でありながら風味があり、さまざまな料理の調味料や薬味として好評を得ています。' where id = '6nn5oh7tqC0WSA2iV94lu';
update content_bodies set title = 'Mimakara Ichimi (Local Food Project Tokushima)', description = 'Mimakara Ichimi is a local specialty made from fully ripened Mimakara chili peppers. The peppers are harvested at their peak, carefully dried, and individually cleaned to remove impurities. They are then roasted in precise quantities and ground slowly using a stone mill to preserve their fibers. This meticulous process results in a fresh and flavorful product that is known for its intense spiciness and rich aroma, making it a popular seasoning and condiment for various dishes.' where id = 'eqN1f_HTt0pky3OsLNt0d';
update content_bodies set title = '自分みがきスポット三重 -尾鷲版-', description = '伊勢から熊野三山へとつながる世界遺産「熊野古道・伊勢路」は、歴史に名を刻む参詣道です。昔の旅人の思いを馳せながらこの道を歩くことで、その奥深さに魅了されることでしょう。夢古道おわせでは、お母ちゃんが作るランチバイキングが特におすすめです！' where id = 'sc0b9W5rAzUnGABtuBWvo';
update content_bodies set title = 'Self-Enhancement Spot in Mie - Owase Version -', description = 'The World Heritage site ''Kumano Kodo - Iseji,'' connecting Ise to the Kumano Sanzan, is a pilgrimage route mentioned in history. Walking along this path while reflecting on the thoughts of ancient travelers will surely captivate you with its depth. At Yumekodo Owase, the recommended option is the lunch buffet prepared by local mothers!' where id = 'oBhRui6z1ptFRRk2quAqr';
update content_bodies set title = '世界的に重要な農業遺産システム、Nishi-awa、Sora no Sato', description = 'この動画は、徳島県の西阿波地域における食、農業、ライフスタイル文化を継承することを目的とした「空の里」の取り組みを紹介しています。この地域は少子高齢化が進んでおり、移住者や農業者を増やし、農業をビジネスとして成り立たせることで地域を持続可能にすることを目指しています。プロジェクトには、都市の学校からの教育旅行や地元の子どもたちへの食と農業文化の教育が含まれています。' where id = 'dGi3uJJ9dFxt8mI-SJ5eR';
update content_bodies set title = 'Globally Important Agricultural Heritage Systems, Nishi-awa, Sora no Sato', description = 'This video presents the initiative by ''Sora no Sato'' aimed at preserving the food, agriculture, and lifestyle culture in the Nishi-Awa region of Tokushima, which faces challenges such as a declining birthrate and an aging population. The project seeks to attract more immigrants and farmers to the area and sustain the community by transforming agriculture into a viable business. It includes educational trips for students from urban schools and local children to teach them about food and farming culture.' where id = 'Z7FzlcQSC1BwiCrSf6Zmf';
update content_bodies set title = '自分みがきスポット三重 -津版-', description = 'ノスタルジーに誘われてイザ寺内町へ！日本で唯一の環濠や伝統的な町屋、土蔵など、情緒あふれる町を散策できます。専修寺内の御影堂や如来堂、宝物館など、国や県指定の文化財も多く、歴史好きには必見のスポットです！' where id = '5FG7BQa3Hzr9sDiSeSUN6';
update content_bodies set title = 'Self-Polishing Spot in Mie - Tsu Edition -', description = 'Invited by nostalgia, visit the historic Izakurai Town! This area features Japan''s only moat, traditional townhouses, and storehouses, making it a charming place to explore. With many cultural properties designated by the national and prefectural governments, including the Gohyakudo and Nyorai-do of Senshu-ji and the Treasure Museum, it is a must-visit spot for history enthusiasts!' where id = 'bq5ZeFdzYBa3Io8m7mt8d';
update content_bodies set title = 'ペイサージュ（にし阿波／そらの郷山里物語）', description = 'この動画は、にし阿波にあるそらの郷山里物語について紹介しています。ペイサージュは、地域の文化や自然をテーマにした物語であり、視聴者にその魅力を伝える内容となっています。' where id = 'dPmbiksFX-J20TmEVp8L3';
update content_bodies set title = 'Peisage (Nishi-Awa / Sora no Sato Yamasato Monogatari)', description = 'This video introduces Peisage, a story about Sora no Sato in Nishi-Awa.' where id = 'jR7zVVrV7Fq-C_SFH6dt1';
update content_bodies set title = 'みかも喫茶（にし阿波／そらの郷山里物語）', description = 'この動画では、にし阿波に位置するみかも喫茶と、そらの郷山里物語に関連するそのストーリーについて紹介しています。' where id = '67ZcaVlqQLLklfdDfOj73';
update content_bodies set title = 'Mikamo Cafe (Nishi-Awa / Sora no Sato Yamasato Monogatari)', description = 'This video introduces Mikamo Cafe, located in Nishi-Awa, and its story related to Sora no Sato Yamasato.' where id = 'eaAGpfcCl2-aHNCVCEtEc';
update content_bodies set title = '岩野家サイクリング', description = 'この動画は岩野家サイクリングについて紹介しています。' where id = 'DOnBXNTP3OJx_kS5k8AAy';
update content_bodies set title = 'Iwano Family Cycling', description = 'This video introduces Iwano Family Cycling.' where id = '3y7tW4AI3jzBDDB9wrIaS';
update content_bodies set title = '岩野家着物体験', description = 'この動画では、岩野家での着物体験について紹介しています。' where id = 'W5cJ6LlsS_mi6IJdWk8hY';
update content_bodies set title = 'Iwano Family Kimono Experience', description = 'This video introduces the Iwano family kimono experience.' where id = '4aTg4E2u_Flt4Mwv72KOP';
update content_bodies set title = 'ラルゴ', description = 'ラルゴは、徳島県にし阿波地域の山中にある家族経営の宿泊施設で、世界農業遺産（GIAHS）に認定されています。教育旅行の受け入れを行い、味噌玉づくり体験を提供しています。「とくしま農林漁家民宿」の認定を受けており、地元の食材や旬の山菜を使った田舎料理やハーブスイーツでおもてなしをしています。季節ごとの野遊び体験やアロマ蒸留体験、日本の薬草の収穫など、アクティブな体験が可能です。また、「うたたねの部屋」ではアロマトリートメントやフットケアのサービスも受けられます（要予約）。お花見やバーベキュー、ヨガ、勉強会などの貸し切り利用も可能で、LGBTQフレンドリーな宿泊施設です。観光地へのアクセスに便利な車の手配も行っています。' where id = 'QBpA8sQRaZhryaUOPkLK1';
update content_bodies set title = 'Largo', description = 'Largo is a family-run accommodation located in the mountains of the Nishi-Awa region in Tokushima Prefecture, recognized as a Globally Important Agricultural Heritage System (GIAHS). They offer educational travel experiences, including a miso ball-making workshop. Certified as a ''Tokushima Agricultural, Forestry, and Fishing Family Inn,'' Largo provides hospitality with local ingredients and seasonal mountain vegetables, along with herb-based sweets. Guests can enjoy various seasonal outdoor activities, aroma distillation experiences, and harvesting Japanese herbs. The accommodation features a room called ''Utatanen no Heya,'' where guests can book services like aroma treatments and foot care. Private bookings for activities such as cherry blossom viewing, barbecues, yoga, and study sessions are also available. Largo is LGBTQ-friendly and offers transportation arrangements for accessing scenic spots with narrow mountain roads.' where id = 'OZf6dpbM3wm01dnoD83ju';
update content_bodies set title = 'そらの郷山里物語', description = '日本のにし阿波地域には、千年以上にわたり受け継がれてきた山里の暮らしがあります。人々は協力して畑を作り、高地性集落「そらの郷」の生活を続けています。この農山村での暮らし体験を通じて、訪れる人々は「Spirit of Japan」を体感することができます。' where id = '2Cvx6E9pl1Voju6DEG-In';
update content_bodies set title = 'Sora no Sato Mountain Village Story', description = 'In the Nishiawa region of Japan, there exists a way of life in the mountain villages that has been passed down for over a thousand years. The residents work together to cultivate fields and maintain the lifestyle of the highland community known as ''Sora no Sato.'' Through experiential learning in this agricultural mountain village, visitors can experience the ''Spirit of Japan.''' where id = 'uotQIFlhOJan_vCCcNWZQ';
update content_bodies set title = '折目邸（にし阿波／そらの郷山里物語）', description = 'この動画では、にし阿波に位置する折目邸について紹介しています。折目邸は、そらの郷山里物語の一部として取り上げられており、その魅力や特徴が伝えられています。' where id = 'aXK8LvRpZYROxMtEbf2Z6';
update content_bodies set title = 'Orome Residence (Nishi-Awa / Sora no Sato Yamasato Monogatari)', description = 'This video introduces the Orome Residence, located in Nishi-Awa, as part of the Sora no Sato Yamasato Monogatari series.' where id = 'KWcnZ7_FH5CMAZaXqzfAh';
update content_bodies set title = 'punta（にし阿波／そらの郷山里物語）', description = 'この動画は、にし阿波とそらの郷山里物語に関連するpuntaについて紹介しています。' where id = 'AJy9S2OUbxGd7QOFAW9v6';
update content_bodies set title = 'punta (Nishi-Awa / Sora no Sato Yamasato Monogatari)', description = 'This video introduces punta, which is related to Nishi-Awa and the story of Sora no Sato Yamasato.' where id = 'd7zQh-fvOmrasfJQDhNzA';
update content_bodies set title = '夜桜を見てきたでござるの巻', description = '三重県津市の津駅から徒歩5分以内にある桜の名所「偕楽公園」で夜桜を見てきました。' where id = 'siUDbCpOSWSP13nbemdui';
update content_bodies set title = 'Viewing Night Cherry Blossoms', description = 'I visited the night cherry blossoms at Kairaku Park, a famous cherry blossom spot located within a five-minute walk from Tsu Station in Tsu City, Mie Prefecture.' where id = 'pStmejiHi2D-W_7yVseUA';
update content_bodies set title = '花より・・・', description = 'お天気の良い日、津市のかいらく公園に子どもと一緒に出かけました。公園では花がだいぶ咲いていて、とても綺麗でした。' where id = 'gKB2AL3TKDi-lmd3WRKhi';
update content_bodies set title = 'More than Flowers...', description = 'On a sunny day, I went out with my child to Kairaku Park in Tsu City. The flowers were in full bloom and beautiful.' where id = 'w7OJEI2YKB5OPVGInHIXO';
update content_bodies set title = '丹波山観光PR 尾根道を歩こう', description = '近年、低山登山が人気を集めており、気軽に自然を身近に感じることができます。これは、山に囲まれた丹波山村ならではの活動です。また、この尾根道は「生活道」として、また「水源管理の作業道」として、当時の人々にとって重要なインフラでした。この道を人々がどのように守り、歩んできたのかを考えてみましょう。' where id = 'mvVJAvpjDjw6eCE0XBWcR';
update content_bodies set title = 'Explore the Ridge Trail in Tanbayama', description = 'In recent years, low mountain hiking has gained popularity, allowing people to experience nature up close without pressure. This activity is unique to Tanba Village, surrounded by mountains. The ridge trail served as an important infrastructure for the local community, functioning as a ''path used for daily life'' and a ''work road for water source management.'' Reflect on how the people of the past preserved and walked this path.' where id = 'U6iAPElNUZKbwlEreZBOu';
update content_bodies set title = 'ミキモト真珠島美しい海女さん', description = 'ミキモト真珠島を訪れ、海女ショーを観覧しました。素晴らしい体験でした。暖かい日でしたが、海は冷たそうでした。冬でも海女たちは潜るそうです。' where id = 'UwVS2bcK5xBXEk-E4n32K';
update content_bodies set title = 'Mikimoto Pearl Island Beautiful Ama Divers', description = 'I visited Mikimoto Pearl Island and watched the ama diver show. It was amazing! Although it was a warm day, the sea looked quite cold. I heard they dive even in winter.' where id = 'N4m2o_Ib-vpCmmOLrXKdn';
update content_bodies set title = 'TABAワークセンター紹介動画「たばやまワーケーション」', description = '声優の雨宮天さんが自然豊かな丹波山村でワーケーションを体験しました。TABAワークセンターは2022年6月に山梨県丹波山村で営業を開始予定で、コワーキングスペースや宿泊可能な個室を備えたテレワーク施設です。施設の詳細はTwitterで発信予定です。丹波山村は東京都と山梨県の県境に位置し、多摩川の上流域にあり、美しい丹波川が流れています。雲取山をはじめとする秩父多摩甲斐国立公園の険しい山々に囲まれ、トレッキングや渓流釣り、キャンプなどの人気スポットが豊富です。江戸時代からの伝統行事が今も受け継がれている小さな村で、仕事や創作の合間に村のアウトドアアクティビティも楽しんでください。' where id = 'CJZ6sq8fwAXiS69wR8gc5';
update content_bodies set title = 'Introduction to TABA Work Center: ''Tabayama Workation''', description = 'Voice actress Sora Amamiya experienced a workation in the nature-rich Tabayama Village. The TABA Work Center, set to open in June 2022 in Yamanashi Prefecture, offers a telework facility with coworking spaces and private rooms for accommodation. More details about the facility will be shared on Twitter. Tabayama Village is located at the border of Tokyo and Yamanashi Prefectures, along the upper reaches of the Tama River, where it transforms into the beautiful Tanba River. Surrounded by the rugged mountains of Chichibu-Tama-Kai National Park, including Mount Kumotori, it is a popular spot for trekking, river fishing, and camping. The village, once a bustling post town during the Edo period, still preserves traditional events from that era. Visitors are encouraged to enjoy outdoor activities in the village during their work or creative breaks.' where id = '1-ylL6glx0qOCXwUcdNqo';
update content_bodies set title = 'さくらんぼ狩り《25粒食べ比べ》プラン♪', description = 'このプランでは、2種類以上のさくらんぼを60分間ゆっくりと食べ比べることができます。見た目や香り、甘さ、酸味など、粒ごとの個性を時間を気にせず楽しむことができます。シーズン中に何度も体験し、自分の「推しさくらんぼ」を見つけてみましょう！詳細はウェブサイトをご覧ください。' where id = 'PkoZIP_ueCPJx3PcGfx1S';
update content_bodies set title = 'Cherry Picking: 25 Varieties Tasting Plan♪', description = 'This plan allows you to leisurely compare two or more varieties of cherries for 60 minutes. You can enjoy the unique characteristics of each cherry, including their appearance, aroma, sweetness, and acidity, without worrying about time. Experience it multiple times throughout the season to find your favorite cherry! For more details, visit the website.' where id = 'kNhNwtfr9ITsi2hptVZ1O';
update content_bodies set title = '雅楽アレンジ「七ツ石の狼、雲を取りに駆ける」', description = '「七ツ石の狼、雲を取りに駆ける」は、絵本『蒼い夜の狼たち』をイメージした楽曲で、作曲はZUNによるものです。この曲は國學院大學の雅楽サークル、光華明彩によって演奏されました。丹波山村の美しい風景と共に、この演奏をお楽しみください。' where id = 'UPloUQsy-aO6mun9SjRWZ';
update content_bodies set title = 'Gagaku Arrangement ''The Wolf of Nanatsuishi, Running to Catch the Clouds''', description = 'The piece ''The Wolf of Nanatsuishi, Running to Catch the Clouds'' is an image song inspired by the picture book ''The Wolves of the Blue Night,'' composed by ZUN. It was performed by the Gagaku circle Kōka Meisai from Kokugakuin University. Enjoy the performance alongside the beautiful scenery of Tanba-yama Village.' where id = 'Ww05eDhDRPNZxCrkb7hMO';
update content_bodies set title = 'さくらんぼ狩り《30分食べ放題》プラン♪', description = '旬のさくらんぼをお腹いっぱい食べられる満足プランです。樹でしっかり熟したたくさんのさくらんぼをお腹いっぱいお召し上がりいただけます。時期によっては数種類を食べ比べもできるかも!? 詳細はウェブサイトをご覧ください。' where id = 'yaTn-WbGhBkV3wWtOqbPY';
update content_bodies set title = 'Cherry Picking Plan: 30 Minutes of Unlimited Eating♪', description = 'This plan allows you to enjoy an abundance of seasonal cherries to your heart''s content. You can eat as many ripe cherries as you like, freshly picked from the trees. Depending on the season, you might even have the opportunity to compare different varieties of cherries! For more details, visit the website.' where id = 'BmrK1B9u5v3Wy0dd1j2rd';
update content_bodies set title = 'オーチャードツーリズムまつかわ', description = '何度でも出会いたくなる人々や自然、暮らしがある南信州まつかわ。ここでの旅は、だんだんと好きになる体験を提供します。南信州の魅力を発見し、まつかわの美しさに触れることで、さらにその魅力に引き込まれることでしょう。詳しくはウェブサイトをご覧ください。' where id = 'm9daPDqZA0VPdDpTwgNCF';
update content_bodies set title = 'Orchard Tourism Matsukawa', description = 'Experience the charm of Matsukawa, where you can meet people, nature, and lifestyle that you want to encounter again and again. Discover the beauty of southern Nagano through a journey that will make you fall in love with Matsukawa more and more. For more details, visit the website.' where id = 'RSRyehXHkZOuPfqDM0YSd';
update content_bodies set title = 'のらくら移住者の声：金田悠', description = '南信州・松川町は、100年続くくだものの里として知られています。移住希望者に寄り添った内容を提供するウェブサイト「まつかわつながる案内所のらくら」（https://norakura.life）は、官民共同で制作・運営されています。松川は2つのアルプスに囲まれ、のらくらと共に人生を楽しむことができます。「のらくら」という言葉は、農を楽しみ暮らしを良くするという意味を込めており、のどかな原風景や野良な情景を想起させます。このサイトを通じて、松川の魅力を多くの人に伝えていきます。南信州まつかわでの出会いを楽しむ旅をぜひ体験してください。' where id = 'GlpdWKdAE2ub1vwt-1aOw';
update content_bodies set title = 'Voices of Norakura Residents: Yu Kaneda', description = 'Matsukawa Town in southern Nagano, known as the land of fruits for over a century, offers a unique living experience. The website ''Norakura Life'' (https://norakura.life) is a collaborative effort between public and private sectors, providing support and information for those considering relocation. Nestled between two mountain ranges, Matsukawa invites residents to enjoy a leisurely lifestyle. The term ''Norakura'' embodies the idea of enjoying agriculture and improving life quality. It also evokes images of serene landscapes and rural scenes, appealing to both visitors and potential newcomers. Through the Norakura website, the charm of this town is shared with everyone. Discover the beauty of Matsukawa and the connections it fosters.' where id = 'ee99bEKdIpMFpWETpCqoJ';
update content_bodies set title = 'のらくら移住者の声：田中大也', description = '南信州・松川町は、100年以上にわたりくだものの里として知られています。ウェブサイト「まつかわつながる案内所のらくら」（https://norakura.life）は、官民共同で制作・運営されており、移住希望者に寄り添った情報を提供しています。2つのアルプスに囲まれた松川では、のらくらと共に人生を楽しむことができます。「のらくら」という言葉は、農を楽しみ暮らしを良くするという意味を持ち、松川ののどかな風景を思い起こさせることを目指しています。このウェブサイトを通じて、松川の魅力を皆さんにお伝えしていきます。人、自然、暮らしとの出会いを何度でも楽しめる南信州・松川の旅をぜひ体験してください。' where id = '4fblNFP3K164QgNPPvT7q';
update content_bodies set title = 'Voices of Norakura Residents: Daisuke Tanaka', description = 'Matsukawa Town in southern Nagano has been known as a fruit-producing area for over 100 years. The website ''Matsukawa Connecting Guide Norakura'' (https://norakura.life) is a collaborative effort between the public and private sectors, providing supportive information for those wishing to relocate. Nestled between two mountain ranges, Matsukawa offers a lifestyle that embraces the joy of living and farming. The term ''Norakura'' conveys the idea of enjoying farming and improving life, while also evoking images of the serene landscapes and fields of Matsukawa. Through the Norakura website, we aim to showcase the charm of this town to both visitors and potential residents. Discover the beauty of Matsukawa and the connections with people, nature, and life that make it a place worth falling in love with repeatedly.' where id = 'LbIeK_TDZRFLoefXdHygv';
update content_bodies set title = 'フォレストアドベンチャー松川に遊びに行ってみた 360°動画', description = 'この動画では、360°カメラを使ってフォレストアドベンチャー松川での体験を撮影し、まるでその場にいるかのような臨場感を提供しています。長野県松川町に位置するこのアウトドアパークは、スリリングなジップラインや空中アスレチックが楽しめる人気スポットで、子どもから大人まで楽しめます。フォレストアドベンチャーを探している方や、長野の観光スポットを知りたい方、家族で楽しめるアクティビティを探している方におすすめです。動画では、自然の美しさとアクティビティのスリルが伝わり、次の旅行先の参考にもなります。詳細はリンクを参照してください。' where id = 'MYnQw-Li9PAULQhhlw18y';
update content_bodies set title = 'Exploring Forest Adventure Matsukawa: A 360° Video', description = 'This video captures the thrilling experience of Forest Adventure Matsukawa using a 360° camera, allowing viewers to feel as if they are actually there. The park, located in Matsukawa, Nagano, is a popular outdoor destination featuring exciting zip lines and aerial courses suitable for both children and adults. It is recommended for those looking for adventure parks, sightseeing spots in Nagano, family-friendly activities, or those interested in zip lines and athletics. The video showcases the beauty of nature and the thrill of the activities, making it a great reference for future trips with family and friends. For more information, visit the provided links.' where id = 'rg60-H67BXSkkBrWJIsJd';
update content_bodies set title = '松川町でEバイクを体験してみた 360°動画', description = '南信州松川町の魅力を360°動画で体験できます。自然とアドベンチャーが融合したこの町の見どころを紹介し、美しい風景を360度から楽しむことができます。オーチャードサイクリングツアーも含まれており、地域をユニークに探索する方法を提供しています。詳細はウェブサイトをご覧いただき、チャンネル登録をお願いします。' where id = 'Z5U5EI-VFVlTG2o0MGt5p';
update content_bodies set title = 'Experience E-Bike Adventure in Matsukawa Town - 360° Video', description = 'Discover the charm of Matsukawa Town through an immersive 360° video that combines nature and adventure. This video showcases must-see spots and the beautiful landscapes of the area, allowing viewers to enjoy the scenery from all angles. The experience includes an Orchard Cycling Tour, providing a unique way to explore the region. For more information, visit the website and subscribe to the channel for updates.' where id = '01nCwd7iGAo5SV6XM32gD';
update content_bodies set title = '梨狩り（南水）', description = '南信州まつかわで、何度でも出会いたくなる人々や自然、暮らしを体験できます。この地域の魅力を発見し、ますます好きになる旅を楽しんでください。詳しくはウェブサイトをご覧ください。' where id = 'CcNiRmbnClBpfaLlSf9DO';
update content_bodies set title = 'Pear Picking (Nansui)', description = 'Experience the charm of Matsukawa in southern Nagano, where you can encounter delightful people, nature, and lifestyle repeatedly. Discover the beauty of this region and enjoy a journey that will make you fall in love with it more and more.' where id = 'Ue0QWVynilV-wy4h3hcUp';
update content_bodies set title = 'りんご狩り　シナノ三兄弟（シナノスイート・シナノゴールド・秋映え）', description = '南信州まつかわで、何度でも出会いたくなる人々や自然、暮らしを体験できます。この地域の魅力やりんごの品種を通じて、ますます好きになる旅をお楽しみください。詳しくはウェブサイトをご覧ください。' where id = '79qGhNSiPallrQVn90MGo';
update content_bodies set title = 'Apple Picking: The Shinano Brothers (Shinano Sweet, Shinano Gold, Akibae)', description = 'Experience the charm of Matsukawa in southern Nagano, where you can encounter delightful people, nature, and lifestyle repeatedly. Discover the beauty of this region and its apple varieties through a journey that will make you fall in love with it more and more.' where id = '8WYK8iZ3zwAl-zRZy_i6_';
