update content_bodies set title = 'Apple Picking (Sun Fuji)', description = 'Experience the charm of Matsukawa in southern Nagano, where you can encounter delightful people, nature, and lifestyle repeatedly. Discover the beauty of this region and enjoy a journey that will make you fall in love with it more and more. For more details, visit the website.' where id = 'uaviTipAFdaGsJUWihe0U';
