update content_bodies set title = 'Gourmet Kingdom Miyagi: 7 Huge Portions That Will Surprise You!', description = 'This video introduces large portion gourmet dishes in Miyagi Prefecture, perfect for those traveling or sightseeing in the area. If you have any recommendations that are not mentioned in the video, please share them in the comments! The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to discover new possibilities and enjoy their journeys. For more information, check out their official social media accounts.' where id = 'R1QT8J3YOE9GNYs_jBao0';
update content_bodies set title = '鴻巣びっくりひな祭り', description = '鴻巣市で380年の歴史を持つ「ひな人形制作」を体験できる「鴻巣びっくりひな祭り」。約7メートルの高さを誇る日本一のひな人形のピラミッドを目の当たりにしながら、日本文化を楽しむことができます。この祭りは、伝統的な日本の工芸や芸術を体験する貴重な機会です。' where id = 'WdxRw7--DsI_CRZ-mKMUg';
update content_bodies set title = 'Konosu Surprising Doll Festival', description = 'The Konosu Surprising Doll Festival, known as ''Konosu Bikkuri Hina Matsuri,'' showcases a rich 380-year history of doll making in Konosu city. Visitors can immerse themselves in Japanese culture while marveling at the impressive doll pyramid, which stands approximately 7 meters tall. This festival is a unique opportunity to experience traditional Japanese craftsmanship and artistry.' where id = 'ntOlxOT0ZV00V8zoI_4ew';
update content_bodies set title = '久慈良品vol.1　おぼろ昆布', description = 'あまちゃんの聖地である岩手県久慈市には多くの魅力があります。久慈市の観光コンテンツを9本の短編動画にまとめており、これらの動画は映画監督の長澤雅彦さんによって制作されています。ぜひ最後までご覧ください。「久慈良品」プロジェクトは、地元の人々にとっては当たり前の「風景」「食べ物」「暮らしぶり」「人」などが、外部の人々にとっては宝物であるという視点から、観光関係者が集まり、これらの宝物を国内外に広く発信することを目指しています。' where id = 'DuNjaMmkaAeln8OFbkpyk';
update content_bodies set title = 'Kuji Products Vol.1: Oboro Kombu', description = 'Kuji City in Iwate Prefecture, known as the sacred place of ''Amachan'', offers numerous attractions. We have compiled nine short videos showcasing the city''s appealing tourist content. These videos are produced by Masahiko Nagasawa, a film director active both domestically and internationally. We encourage you to watch them until the end. The ''Kuji Products'' project aims to highlight local treasures, such as ''scenery'', ''food'', ''lifestyle'', and ''people'', which may seem ordinary to locals but are considered treasures by outsiders. This initiative brings together tourism stakeholders to promote these treasures widely both in Japan and abroad.' where id = 'HM2ywRVzCChK08kYHyMic';
update content_bodies set title = '久慈良品vol.4　久慈渓谷', description = '岩手県久慈市は「あまちゃん」の聖地として知られ、多くの魅力があります。久慈市の観光コンテンツを9本の短編動画にまとめており、これらの動画は映画監督の長澤雅彦さんによって制作されています。ぜひ最後までご覧ください。「久慈良品」プロジェクトは、地元の人々にとっては当たり前の「風景」「食べ物」「暮らしぶり」「人」などが、外部の人々にとっては宝物であるという視点から、観光関係者が集まり、これらの宝物を国内外に広く発信することを目指しています。' where id = 'fYj8-ec4bcG_yMafrKL8l';
update content_bodies set title = 'Kuji Products Vol. 4: Kuji Valley', description = 'Kuji City in Iwate Prefecture, known as the sacred place of ''Amachan,'' offers numerous attractions. We have compiled nine short videos showcasing the appealing tourist content of Kuji City. These videos are produced by Masahiko Nagasawa, a film director active both domestically and internationally. We encourage you to watch them until the end. The ''Kuji Products'' project aims to highlight local treasures, such as landscapes, food, lifestyles, and people, which may seem ordinary to locals but are considered valuable by outsiders. This initiative brings together tourism stakeholders to promote these treasures widely both domestically and internationally.' where id = 'rdMsL9peD9kCn1EVzK8QW';
