update content_bodies set title = 'Must-Visit Tourist Spots in Okayama, the Land of Momotaro: Complete Guide to 7 Classic Attractions', description = 'This video serves as a guide for those traveling to Okayama Prefecture, showcasing seven classic tourist spots that should not be missed. If you have any additional recommendations not covered in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on various travel aspects, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities and experiences. For more information and updates, follow their official social media accounts.' where id = 'ebhEGiAvOqOE7itGXFiV0';
update content_bodies set title = '【三重観光/グルメ】ガイドブックに載らない！桑名の観光とグルメの超穴場を巡る旅7選', description = 'この動画は三重県桑名市の観光スポットを紹介するもので、旅行や観光の参考に役立ちます。視聴者には、他のおすすめスポットをコメントでシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることがミッションであり、メンバーは年間の半分を旅に費やしています。動画では、文化的な場所や食事の選択肢を含む7つのユニークなスポットが紹介されており、訪問前に公式情報を確認する重要性が強調されています。' where id = 'S_7SCSWdy16Yf_LDYaUwQ';
update content_bodies set title = 'Hidden Gems of Kuwana: 7 Must-Visit Spots for Sightseeing and Gourmet in Mie', description = 'This video serves as a guide for those traveling to Mie Prefecture, specifically highlighting recommended spots in Kuwana City. It encourages viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information on sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video features seven unique locations, including cultural sites and dining options, and emphasizes the importance of checking official sources for the latest information before visiting.' where id = 'Jfn3UzWSHf2Nv55oFoQEH';
update content_bodies set title = 'ガイド付きで学ぶ原発事故からの再生', description = '「ガイド付きで学ぶ原発事故からの再生」は、原発事故からの復興における放射線の知識と食の安全について学ぶ旅を提供します。このプログラムでは、移動に公共交通機関を利用し、周辺環境を紹介するイメージ動画が含まれています。' where id = 'zW0yRsj2IbUwGV1KKqGq4';
update content_bodies set title = 'Learn With a Guide, the Rebirth From a Nuclear Accident (New Tohoku Journey)', description = 'This program offers a guided journey focused on understanding radiation knowledge and food safety in the context of recovery from a nuclear accident. It includes an image video that showcases the content of the journey, the use of public transportation for travel, and the surrounding environment.' where id = 'sO5XI0wqEU6UCyfUHnJa5';
update content_bodies set title = '浄土ヶ浜の絶景と太平洋漁師に出会う旅', description = 'この旅は、１泊２日で浄土ヶ浜の絶景を楽しみ、太平洋の漁師と出会うことを目的としています。公共交通機関を利用した移動や周辺環境を紹介するイメージ動画が含まれており、旅行の魅力を伝えています。' where id = 'hycx4nbB_tq1R4iexz18c';
update content_bodies set title = 'With a Superb View of the Scenic Spot ''Jodogahama'' (New Tohoku Journey)', description = 'This is a travel experience that lasts for two days and one night, focusing on the breathtaking views of ''Jodogahama'' and the opportunity to meet Pacific fishermen. The content includes an image video that introduces the journey, highlighting the use of public transportation for travel and the surrounding environment.' where id = 'pYJ_lXKsq4BsSAyb1ZGw0';
