update content_bodies set title = '日和佐うみがめ博物館 カレッタコース（美波町）', description = '日和佐うみがめ博物館 カレッタは、道の駅日和佐サテライトステーションに指定されており、美波町日和佐周辺の魅力的なエリアを紹介しています。このコースでは、JR日和佐駅、薬王寺、うみがめマリンクルーズ、そして日和佐うみがめ博物館 カレッタを訪れることができます。' where id = 'asnGe4Gyj8QazV61uLDbp';
update content_bodies set title = 'Hiyowasa Sea Turtle Museum Caretta Course (Minami Town)', description = 'The Hiyowasa Sea Turtle Museum Caretta, designated as a satellite station of the Hiyowasa Roadside Station, showcases the attractive areas around Hiyowasa in Minami Town. The course includes stops at JR Hiyowasa Station, Yakushiji Temple, a sea turtle marine cruise, and the Hiyowasa Sea Turtle Museum Caretta.' where id = 'QXIik0TOblXB6RUB7xuIm';
update content_bodies set title = '南阿波サンラインコース（美波町・牟岐町）【「道の駅日和佐サテライトステーション」推進協議会】', description = '南阿波サンラインコースは、道の駅日和佐サテライトステーションに指定されている南阿波サンライン第一展望台を中心に、牟岐町と美波町の魅力的なエリアを紹介しています。主な見どころには、道の駅日和佐、南阿波サンライン第一展望台、内妻海岸、そしてとどろの滝があります。' where id = '0rQQ57odaLoaaLNMk8j-l';
update content_bodies set title = 'Minami Awa Sunline Course (Minami Town and Mugi Town) [Promotional Council for Biyorasa Satellite Station]', description = 'The Minami Awa Sunline Course, centered around the first observatory of the Minami Awa Sunline, showcases the attractive areas of Mugi Town and Minami Town. Key highlights include the Biyorasa Road Station, the first observatory, the Uchizuma Coast, and the Todoro Falls.' where id = 'VrrmkfdAIwGqO2f-zspJR';
