update content_bodies set title = 'Shell Museum Morasuko Mugi Course (Mugi Town)', description = 'The Shell Museum Morasuko Mugi, designated as a satellite station of the Michi no Eki Hiyosato, showcases the attractive areas of Mugi Town. The route includes JR Mugi Station, Mugi Port, and Dejima Island, leading to the Shell Museum.' where id = 'Qancp7WPFz3YIJhGXLEse';
