update content_bodies set title = 'Discover the Hidden Scenic Spots of Tottori! 7 Must-Visit Emotional Locations【Tottori Travel/Tourism】', description = 'This video serves as a guide for those planning to travel to Tottori Prefecture, showcasing seven breathtaking scenic spots. If you have any recommendations that are not mentioned in the video, please feel free to share them in the comments section. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on various travel aspects, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 'ZzYmPBicbca9FNwTs4CEc';
update content_bodies set title = '【阿寒の食と自然】釧路市阿寒町特産PR', description = '釧路市の内陸に位置する自然豊かな町「阿寒町」は、都市部や空港、高速道路からも近く、都市と自然が調和した場所です。この動画では、阿寒町の特産品を紹介しています。動画内で紹介される商品の一部は、ふるさと納税を通じて購入可能ですので、ぜひご覧ください！2024年度からは、待望の動画コンテンツを順次配信予定ですので、チャンネル登録をお願いします。また、InstagramやX（旧Twitter）でも最新情報を発信しています。' where id = 'nbapyzjBTHEe-2VS_A0eA';
update content_bodies set title = 'Akan''s Food and Nature: Promotion of Special Products from Akan Town, Kushiro City', description = 'Akan Town, located inland in Kushiro City, is a place rich in nature, conveniently situated near urban areas, airports, and highways. This video introduces various local specialties from this naturally abundant area. Some of the products featured in the video can also be purchased through the hometown tax system. Be sure to check them out! Starting from the fiscal year 2024, we plan to release much-anticipated video content sequentially, so please subscribe to our channel. You can also follow us on social media platforms like Instagram and X (formerly Twitter) for more updates.' where id = 'a8fHpUDrClzqVYIWV4q8D';
update content_bodies set title = '大分旅行に欠かせない！おすすめ人気グルメ７選', description = '大分県への旅行や観光に役立つ情報を提供する動画で、人気のグルメを紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくするための情報を発信しています。メンバーは旅行を通じて人生を豊かにすることを目指しており、視聴者が新しい可能性を発見できるようサポートしています。公式のSNSアカウントもぜひチェックしてください。' where id = 'MqeA6YeqdZACXq-I614B2';
