update content_bodies set title = '越前市の人気観光スポットと美味しいグルメ７選', description = 'この動画は福井県への旅行を考えている方に向けて、越前市のおすすめ観光スポットを紹介しています。視聴者には、動画で紹介されていないおすすめスポットをコメントでシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見するきっかけを提供したいと考えています。動画では、紫式部公園や岡太神社など、越前市の7つの注目スポットが紹介されており、各スポットの詳細はタイムスタンプで確認できます。' where id = 'puY_MXsfuXgLKjqg8b2ot';
