update content_bodies set title = 'Mount Akagi ROUND TRIP (Summer Edition) - Promotional Movie for the Akagi Mountain Area', description = 'The Akagi Mountain Regional Promotion Council has produced a video titled ''Mount Akagi ROUND TRIP,'' featuring actress Miyu Tejima, who resides in Maebashi City, as the guide. This road movie-style video showcases the charm of Mount Akagi, highlighting refreshing summer landscapes, fireflies, and unique summer festivals. We encourage you to watch it and experience the beauty of the area.' where id = '5IJy0eMcYJys7gOibntqv';
update content_bodies set title = '温泉群馬「湯けむりの出会い」', description = '群馬県は450以上の源泉を有し、様々な泉質を持つ「温泉王国」として知られています。日本有数の名湯から一軒宿の秘湯まで、個性豊かな温泉が揃っています。群馬で極上の温泉体験を楽しんでみませんか。' where id = 'eNCuodDgJXwdVG_YsoWvZ';
