update content_bodies set title = '福島で味わえるコスパグルメ７選', description = '福島県への旅行や観光に役立つ情報として、コスパの良いグルメを７つ紹介する動画です。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を提供しています。「旅行で人生を豊かにする」というミッションのもと、視聴者が新しい可能性を発見できるようサポートしています。公式SNSアカウントもぜひフォローしてください。' where id = 'RvafZSFrh06hK-fqNdJaW';
