update content_bodies set title = '7 Recommended Drive Spots in Tokushima for Sightseeing', description = 'This video serves as a guide for those traveling to Tokushima Prefecture, highlighting seven enjoyable drive spots. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in enriching lives through travel and seeks to inspire viewers to discover new possibilities and experiences. For more information, viewers can follow the official Instagram and Twitter accounts, as well as subscribe to the channel for updates.' where id = 'vC9B_bt6GfhLUlZl_Wwx4';
update content_bodies set title = '七飯町特産品ＰＲ映像（ワイン、地ビール、日本酒）', description = '北海道七飯町の特産品を紹介するPR映像が制作されました。七飯町は、ワイン、地ビール、日本酒を製造している町であり、地域の特産品を広く知ってもらうことを目的としています。映像には、株式会社はこだてわいん、株式会社大沼ブロイハウス、箱館醸蔵有限会社など、地元の企業が撮影協力しています。' where id = 'dabCShu5DQQ13p0Qq4J0v';
update content_bodies set title = 'Promotional Video for Special Products of Nanae Town (Wine, Craft Beer, Sake)', description = 'A promotional video has been created for the special products of Nanae Town in Hokkaido. Nanae Town is known for producing wine, craft beer, and sake. The video features collaborations with local businesses, including Hakodate Wine, Onuma Beer, and Hakodate Brewery.' where id = 'R4ofrrKpLZg-G5ZdbiJj8';
update content_bodies set title = '【七飯町】アクティビティＰＶ　～夏編～', description = '七飯町の夏に体験できるアクティビティコンテンツを紹介する動画が作成されました。この動画では、カヌー、ゴルフ、キャンプ、パラグライダーなど、さまざまなアクティビティが紹介されています。各コンテンツへの予約は、事業者様へ直接行う必要があります。また、冬編の動画も用意されており、七飯町の体験観光ページでは、さらに詳細な情報が提供されています。撮影には、函館七飯スノーパークや北海道カントリークラブなどの協力があり、地域の魅力を伝える内容となっています。' where id = 'KRn9fH934XE2PBtjJaTQN';
update content_bodies set title = 'Nanae Town Summer Activities PV', description = 'A video has been created to introduce the activity content that can be experienced in Nanae Town during the summer. Reservations for each activity should be made directly with the respective operators.' where id = 'PPKtLNZOVBfa39qfOF8ce';
update content_bodies set title = '城岱の夜景', description = '城岱スカイラインの頂上付近にある駐車場から夜景を楽しんできました。美しい夜景が広がっており、特に冬の期間は11月上旬から4月下旬まで通行止めとなるため、訪れる際は注意が必要です。冬の間はアクセスが制限されるため、行くタイミングを考慮することが大切です。' where id = 'cm5c621gdVzOSzp3zqolI';
update content_bodies set title = 'Night View from Jodai', description = 'I visited the night view from the parking area near the top of the Jodai Skyline. The Jodai Skyline is closed to traffic from early November to late April during the winter season.' where id = '6vuScI1V9F7CbsVzr8xZb';
update content_bodies set title = '新緑の大沼', description = '大沼国定公園は北海道亀田郡七飯町に位置しています。5月から6月にかけて、若々しい新緑の大沼の美しい景色を楽しむことができます。ぜひ皆様も大沼を訪れてみてください。' where id = 'pgKnWv5739TNEII7Hcayn';
update content_bodies set title = 'Fresh Green Ounuma', description = 'Ounuma National Park is located in Nanae Town, Kameda District, Hokkaido. From May to June, visitors can enjoy the vibrant fresh green scenery of Ounuma. We invite everyone to come and experience Ounuma.' where id = 'JyjAjM0_KQ9CQEWwbvE_O';
update content_bodies set title = '石川で食べたいデカ盛りグルメ７選', description = 'この動画は石川県への旅行や観光の参考として、デカ盛りグルメを７つ紹介しています。動画に紹介されていないオススメがあれば、コメント欄でシェアしてください。また、旅行の達人の公式LINEアカウントでは、お得な旅行情報を配信しています。このチャンネルは、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。' where id = '3oeORTRiwekZ6Xyv7cyId';
