update content_bodies set title = 'Top 7 Must-Visit Popular Spots in Fukuoka for an Enjoyable Trip', description = 'This video serves as a guide for those traveling to Fukuoka Prefecture, showcasing seven popular tourist spots. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more updates and travel tips, you can follow their official social media accounts.' where id = 'M0P4U_-bKKW9PKslsJK6d';
update content_bodies set title = '観光でも楽しめる香川のパワースポット７選', description = '香川県の旅行や観光に役立つパワースポットを7つ紹介する動画です。視聴者には、他のおすすめスポットをコメントでシェアするよう促しています。このチャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。紹介されるスポットには、金刀比羅宮、善通寺、屋島寺などが含まれています。訪れる前に公式サイトで最新情報を確認することが推奨されています。' where id = 'o0jXK4Pai7LL111HMpl5e';
update content_bodies set title = '7 Power Spots in Kagawa for Tourism', description = 'This video introduces seven power spots in Kagawa, Japan, ideal for travelers and tourists. It encourages viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video details specific locations, including Konpira Shrine, Zentsuji Temple, and Yashima Temple, among others. Viewers are advised to check official websites for the latest information before visiting these spots.' where id = '9rKb_oRXaf6IW0QefPmjX';
update content_bodies set title = '広島を観光するなら巡ってみたい温泉スポット７選', description = 'この動画は広島県への旅行を計画している方に向けて、広島の温泉スポットを7つ紹介しています。視聴者には、他のおすすめスポットがあればコメントでシェアしてほしいと呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。詳細は公式SNSアカウントをフォローし、チャンネル登録をすることで得られます。' where id = 'kTz8GbankEwvIVWYoiADJ';
update content_bodies set title = '7 Must-Visit Hot Spring Spots in Hiroshima', description = 'This video serves as a guide for those traveling to Hiroshima Prefecture, showcasing seven recommended hot spring spots. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in enriching lives through travel and seeks to inspire viewers to discover new possibilities and experiences. For more information, viewers can follow the official social media accounts and subscribe to the channel.' where id = 'P2ldtlfUyvzoAObUPkuGU';
update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　ショート”金刀比羅神社”編', description = '日本本土最東端に位置する根室は、一般的な北海道の魅力とは異なる独自の体験を提供します。北海道民でさえあまり知らない、深い魅力を持つ根室の観光地を紹介する動画が『DEEP HOKKAIDO NEMURO』というコンセプトのもと制作されました。グルメ、自然、文化をテーマに根室の魅力を伝えています。詳細は根室観光NAVIのウェブサイトをご覧ください。' where id = '6X-YnGCFylPxt1vH4fEAF';
update content_bodies set title = 'Nemuro City Tourism PR Video: DEEP HOKKAIDO NEMURO - Short ''Kongōji Shrine'' Edition', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique experience that differs from the typical Hokkaido charm. It showcases a deep and lesser-known side of Hokkaido, even to many locals. The video introduces the attractions of Nemuro under the concept of ''DEEP HOKKAIDO NEMURO'', highlighting its gourmet, nature, and culture. For more information, visit the Nemuro Tourism NAVI website.' where id = 'k7-BYrz92NrtNAG6ymMnJ';
