update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　ショート”根室半島チャシ跡”編', description = '日本本土最東端の根室は、一般的な北海道の魅力とは異なる独自の体験を提供します。北海道民でさえあまり知らない、根室のディープでユニークな側面を紹介する動画です。『DEEP HOKKAIDO NEMURO』というコンセプトのもと、グルメや自然、文化など根室の魅力を伝えています。詳細は根室観光NAVIのウェブサイトをご覧ください。' where id = '7XPhzQzDav5nVGc7RGr-w';
update content_bodies set title = 'Nemuro City Tourism PR Video: DEEP HOKKAIDO NEMURO - Short Edition on the Chashi Ruins of Nemuro Peninsula', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique experience that differs from the typical Hokkaido charm. It showcases a deep and lesser-known side of Hokkaido, even to its residents. The video introduces the attractions of Nemuro under the concept of ''DEEP HOKKAIDO NEMURO,'' highlighting its gourmet, nature, and culture. For more information, visit the Nemuro Tourism NAVI website.' where id = 'FL6fG37oaOQ38FByH8NhI';
update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　ショート”さんま祭り”編', description = '日本本土最東端に位置する根室は、一般的な北海道のイメージとは異なる独自の体験を提供します。北海道民でさえあまり知らない、根室の深い魅力を紹介する動画が『DEEP HOKKAIDO NEMURO』というコンセプトのもと制作されました。グルメ、自然、文化をテーマにした根室の魅力を伝えています。詳細は根室観光NAVIのウェブサイトをご覧ください。' where id = 'BG7Nk6kNI_DOn_GbZnt79';
update content_bodies set title = 'Nemuro City Tourism PR Video: DEEP HOKKAIDO NEMURO - Short ''Sanma Festival'' Edition', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique experience that differs from the typical Hokkaido image. It showcases a deep and lesser-known side of Hokkaido, even to its own residents. The video introduces the attractions of Nemuro under the concept of ''DEEP HOKKAIDO NEMURO,'' highlighting its gourmet, nature, and culture. For more information, visit the Nemuro Tourism NAVI website.' where id = 'qXRYTHlT15c3f62wdvgLC';
update content_bodies set title = '【青森観光】青森で行ってみたい穴場観光スポット７選', description = '青森県への旅行や観光を計画している方に向けて、青森県の穴場観光スポットを7つ紹介する動画です。動画で紹介されていないおすすめスポットがあれば、コメント欄でシェアしてください。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行を通じて人生を豊かにすることを目指しています。視聴者が新しい可能性を発見できるよう、旅行の楽しさを広めることを大切にしています。公式SNSアカウントをフォローして、旅行の最新情報をチェックしてください。' where id = 'j3LG84Lf2fDHqDiKulQlv';
