update content_bodies set title = '阿寒の魂', description = '「阿寒の魂」は、北海道の阿寒湖温泉地域で3シーズンにわたり撮影されたノンバーバルドキュメンタリーです。この作品は、アイヌの人々の日常生活や文化を探求し、美しい自然や地域の伝統的な職人技を紹介しています。言葉を使わずに物語を伝える挑戦的な試みであり、視覚的なストーリーテリングを通じてアイヌ文化の本質に触れることができます。制作に関わったすべての人々に感謝の意を表し、このプロジェクトを通じて得た深い学びについても振り返っています。この作品は、さまざまな国際映画祭で多くの賞を受賞し、その芸術的および文化的な重要性が評価されています。' where id = 'Fg4nb8tcZGSQEE9mEM8Oi';
update content_bodies set title = 'Akan Soul', description = 'Akan Soul is a non-verbal documentary filmed over three seasons in the Lake Akan Onsen area of Hokkaido, Japan. The film explores the daily lives of the Ainu people and their culture, showcasing the beautiful nature and traditional craftsmanship of the region. The project was a challenging attempt to convey stories without words, allowing the audience to connect with the essence of the Ainu culture through visual storytelling. The filmmaker expresses gratitude to everyone who contributed to the project and reflects on the deep learning experience gained through this endeavor. The film has received multiple awards and selections at various international film festivals, highlighting its artistic and cultural significance.' where id = 'HTlZk5AZ-wY9de6TrZ8a_';
update content_bodies set title = '【大分観光/グルメ】大分の定番グルメとなる郷土料理やご当地グルメが味わえるスポット7選', description = '大分県への旅行や観光を考えている方に向けて、大分のグルメスポットを7つ紹介する動画です。地元の郷土料理やご当地グルメを楽しめる場所が紹介されており、視聴者からのオススメもコメント欄でシェアしてほしいとのことです。このチャンネルは、観光や宿泊、食事など、旅行をより楽しくする情報を提供することを目的としています。旅行を通じて人生を豊かにすることを目指しており、視聴者が新しい可能性を発見する手助けをしたいと考えています。' where id = 'a99h73h48m3IduAF5jWDm';
