update content_bodies set title = '7 Hidden Spots to Enjoy in Fukui Tourism', description = 'This video serves as a guide for those traveling to Fukui Prefecture, introducing seven hidden tourist spots. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and hopes to inspire viewers to discover new possibilities and enjoy their journeys. For more information and updates, viewers can follow the official social media accounts.' where id = 'hTUBiYdCyWP58jzF7it0G';
update content_bodies set title = '只見線｜秘境をゆく', description = '只見線は、静けさに包まれた奥会津を走る秘境路線です。この映像は、残雪の季節である3月下旬に撮影され、春の気配が漂う中、列車が山あいを進む様子を捉えています。列車の旅は健気でゆっくりとしたものであり、沿線の美しい風景が映し出されています。なお、一部の空撮映像は、安全に配慮して撮影され、関係機関への確認・手続きが行われています。この映像は地域や風景の魅力を伝えることを目的としており、収益化を主目的としたものではありません。' where id = 'V1SG07Q7ljDmS_vTQUvbl';
update content_bodies set title = 'TADAMI LINE – Into the Heart of Hidden Japan', description = 'The Tadami Line is a remote train route that runs through the serene Oku-Aizu region of Japan. This cinematic journey captures the beauty of the line in late March, when remnants of snow still linger and the signs of spring begin to emerge. The film emphasizes the tranquil and slow-paced nature of the train ride, showcasing the stunning landscapes along the way. It is important to note that some aerial footage was captured with the necessary safety precautions and permissions from relevant authorities. The primary aim of this film is to convey the charm of the region and its scenery, rather than to generate profit.' where id = 'fRmkMrpe9_wIE4Ot2jy6m';
update content_bodies set title = 'ひがし北海道カヌー〜釧路川下り〜', description = 'こんなに手軽にできると思いませんでしたが、本格的な大自然が広がっていました。心の深いところが癒された気がしました。' where id = '2tC7vIkSq_0v6jwpmCu4g';
update content_bodies set title = 'Canoeing in Eastern Hokkaido - Down the Kushiro River', description = 'I didn''t expect it to be so easy! However, there was a vast and authentic natural landscape. I felt a deep sense of healing in my heart.' where id = 'r_jb6wkmAWuEqqPjz-57-';
update content_bodies set title = '【2019】弟子屈高校制作 観光紹介動画', description = 'この動画は、弟子屈高校の有志の生徒たちが「てしかがえこまち推進協議会」の協力を受けて制作しました。彼らは自分たちの故郷である弟子屈の素晴らしさを世界に伝えたいと考えています。動画の内容は2019年3月のもので、弟子屈の魅力を感じてもらえるように作られています。ぜひご覧いただき、友人にもシェアしてください。' where id = 'MhmrLwp2-h2isJ6rTHTiJ';
update content_bodies set title = '【2019】Teshikaga H.S.production. Sightseeing introduction video', description = 'This video was created by enthusiastic students from Teshikaga High School, with the support of the Teshikaga Eco Town Promotion Council. The students aim to showcase the beauty of their hometown, Teshikaga, located in Hokkaido, Japan. The content reflects the charm of the area as of March 2019. Viewers are encouraged to enjoy the video and share it with friends to spread awareness about Teshikaga.' where id = 'Kp0HKq_thiFVmL4NM7V2-';
