update content_bodies set title = '佐渡港エクスカーション No.4', description = 'このエクスカーションでは、自然豊かな佐渡島の魅力を探ります。特に、両津山（マウントドンデン）、トキの森公園、そして大善神社といった名所を訪れます。参加者は、佐渡の豊かな生態系を象徴する有名な鳥「トキ」との出会いを楽しむことができます。' where id = 'pIYKaYV6_Ldj2KCET8x3d';
update content_bodies set title = 'Sado Port excursion No.4', description = 'This excursion focuses on the natural beauty of Sado Island, featuring notable sites such as Mount Donden, Toki Forest Park, and Daizen Shrine. Participants will have the opportunity to encounter the famous bird ''Toki,'' which symbolizes the rich biodiversity of the area.' where id = '_qQ6wn6qVSPixIFfMA-9X';
update content_bodies set title = '【日本国際観光映像祭共同制作】Amazing from the Inside,KOKA,Japan,ART&FACTORY JAPAN 2023', description = '日本国際観光映像祭2023滋賀大会において、共同制作が行われました。ブラジルの映像作家が招かれ、甲賀の街を歩きながら人々と出会い、彼らの体験を表現しました。このプロジェクトは、ポルトガルの国際観光映像祭ART&TURにおいて、Art&Creativity部門で2位を受賞しました。' where id = 'DbK8RViUw6AOFzhgb7cuK';
update content_bodies set title = 'Amazing from the Inside, KOKA, Japan, ART&FACTORY JAPAN 2023', description = 'At the 2023 Shiga edition of the Japan International Tourism Film Festival, a collaborative production took place. Brazilian filmmakers were invited to walk through the city of Koka, meet its people, and express their experiences. The project won second place in the Art&Creativity category at the international tourism film festival ART&TUR in Portugal.' where id = 'rkUlPWyl92bZwrOZiaV0e';
update content_bodies set title = '福島を観光するなら絶対に行きたい絶景スポット７選', description = 'この動画は福島県を訪れる旅行者のためのガイドで、絶景の観光スポットを7つ紹介しています。動画に載っていないおすすめがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。運営メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性や体験を探求することを奨励しています。最新情報や旅行のヒントを得るために、公式のSNSアカウントをフォローすることもできます。' where id = 'mkqIaThLP_jbfFwiMH_DH';
update content_bodies set title = '7 Must-Visit Scenic Spots in Fukushima for Your Trip', description = 'This video serves as a guide for those traveling to Fukushima Prefecture, showcasing seven breathtaking tourist spots. If you have any recommendations that are not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities and experiences. For more updates and travel tips, you can follow their official social media accounts.' where id = 'bTxlikKRoHRfaddC8MRZ_';
