update content_bodies set title = '【栃木観光/グルメ】栃木グルメを堪能するならカフェ・スイーツは欠かせない。人気カフェスポット７選', description = 'この動画は栃木県を訪れる旅行者に向けて、人気のカフェやスイーツを紹介しています。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。また、旅行の達人の公式LINEアカウントでは、旅行に関するお得な情報を配信しています。このチャンネルは、観光、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。' where id = 'EbugIVBdjcbtWJfz4FMj9';
