update content_bodies set title = '伊藤健太郎のただいま信楽', description = '甲賀ロケーション推進協議会が制作した観光PV「伊藤健太郎のただいま信楽」について紹介します。ドラマの撮影以来、数年ぶりに信楽を訪れた伊藤健太郎は、ロケ中には感じられなかった信楽のまちの雰囲気や温かさに触れました。この動画をぜひご覧いただき、甲賀市信楽へお越しください！' where id = 'zHmQMMxGFoqw3ikvIHojr';
update content_bodies set title = 'Kentarou Ito''s Return to Shigaraki', description = 'The Kouka Location Promotion Council has produced a tourism promotional video titled ''Kentarou Ito''s Return to Shigaraki.'' After several years since filming a drama, Ito revisited Shigaraki and experienced the town''s atmosphere and warmth that he couldn''t feel during the shoot. We encourage everyone to watch the video and visit Kouka City, Shigaraki!' where id = 'zigv-O4YMHDECTYTFJ3FN';
