update content_bodies set title = 'Oita Prefecture: Oita''s Onsen Tourism Video - Takeda City: Activity Version', description = 'This promotional video showcases activities in Takeda City, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video highlights attractions such as the Takeda City Historical Literature Museum and horseback riding experiences. It serves as a great reference for travelers looking to explore the region. For more information, visit the official Oita tourism website.' where id = 'tavyZyZpx_youWl2NtGJA';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～姫島村：2分ver.～', description = '大分県の観光PR動画「姫島村編」では、日本一の温泉県である大分県の姫島村の魅力を紹介しています。姫島盆踊りやアサギマダラ、姫島車えびなど、観光名所が盛りだくさんです。この動画は、姫島村を訪れる際の参考になるでしょう。詳しい情報は大分県観光情報公式サイトをご覧ください。' where id = 'EHNllpQNfdE6-Rg0Sdhra';
update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Himeshima Village: 2-Minute Version', description = 'This is a promotional video for Himeshima Village, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video showcases the village''s attractions, including the Himeshima Bon Odori dance, the Asagimadara butterfly, and Himeshima shrimp. It serves as a great reference for travelers looking to explore the charm of Himeshima Village. For more information, visit the official Oita tourism website.' where id = 'Y1G_-ty8KYtyZkpxkzXKr';
update content_bodies set title = '新潟県長岡市で行ってみたい観光スポットと人気のグルメ７選', description = 'この動画は新潟県への旅行を考えている方に向けて、長岡市の観光スポットと人気のグルメを紹介しています。視聴者には、動画で紹介されていないおすすめ情報をコメント欄でシェアするよう促しています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。運営メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。動画では、新潟県立歴史博物館や長岡まつり大花火大会など、７つのおすすめスポットの詳細が紹介されています。訪問前には公式サイトで情報を確認することが推奨されています。' where id = 'd7M16T4BvJk6EPljWGbHa';
update content_bodies set title = 'Tourist Attractions and Popular Gourmet in Nagaoka City, Niigata Prefecture', description = 'This video serves as a guide for those traveling to Niigata Prefecture, specifically highlighting tourist spots and popular gourmet options in Nagaoka City. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information related to sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities through their journeys. The video includes details about seven recommended locations, including the Niigata Prefectural Museum of History and the Nagaoka Festival Fireworks. For more information, viewers are advised to check official websites before visiting.' where id = 'VD1ibHPxwyQ689ncW7972';
update content_bodies set title = '岐阜を観光するなら絶対行きたいパワースポット７選', description = 'この動画は岐阜県への旅行を計画している方に向けて、訪れるべきパワースポットを7つ紹介しています。視聴者には、他のおすすめスポットがあればコメントでシェアしてほしいと呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、国内外の旅行情報を提供し、旅行をより楽しくすることを目的としています。運営チームは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見し、人生をより良くするきっかけを提供したいと考えています。最新情報は公式SNSアカウントをフォローすることで得られます。' where id = 'OsNiqd2GKhvvSH7qMArbD';
