update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～姫島村：アクティビティver.～', description = '大分県の観光PR動画「姫島村：アクティビティ」を紹介します。大分県は日本一の温泉県として知られています。この動画では、エコカードドライブやお面絵付け体験などのアクティビティが紹介されています。旅行の参考にぜひご覧ください。詳細は大分県観光情報公式サイトをご覧ください。' where id = '_KWmH1ZdcdlCQexZsHMmH';
update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Himeshima Village: Activity Version', description = 'This is a promotional video for tourism in Oita Prefecture, showcasing Himeshima Village and its activities. Oita is known as Japan''s number one onsen (hot spring) destination. The video features activities such as eco-card driving and mask painting experiences. It serves as a great reference for travelers looking to explore the region. For more information, visit the official Oita tourism website.' where id = 'dfDSOeQibdw-kCe7efLNC';
update content_bodies set title = '鳥羽をまるごと体験！！', description = 'ミスインターナショナル2023フランス代表のリシアとパートナーのローメンが再度鳥羽を訪れました。彼らは1ヶ月間の滞在中に、さまざまなことに挑戦し、鳥羽の魅力を存分に体験しました。' where id = 'ZZ_Xb9sYB4JD5v0Em0CCv';
