update content_bodies set title = 'どんちっちはまだ【島根県浜田市観光PR動画（公式）】', description = '島根県浜田市の観光プロモーション動画『どんちっちはまだ』が公開されました。この動画では、浜田市の魅力を余すところなく紹介しており、海や山、伝統的な石見神楽が楽しめることを伝えています。浜田市の自然と文化・歴史が息づく様子を映し出し、観光スポットとして石見畳ヶ浦や島根県立石見海浜公園、地元のカフェなどが紹介されています。訪れる人々に、浜田市の独自の魅力を体験してもらうことを目的としています。' where id = 'XIYgst5PnRMO5Nwt5ojS4';
