update content_bodies set title = 'Hidden Tourist and Gourmet Spots in Tanabe City, Wakayama: 7 Recommendations', description = 'This video serves as a guide for those traveling to Wakayama Prefecture, specifically highlighting hidden spots in Tanabe City, which is a junction for the Kumano Kodo and Ohechi routes. Viewers are encouraged to share their own recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities through their journeys. For more information and updates, viewers can follow the official social media accounts.' where id = 'yPCJXyTp0yiO4KdT-6ACl';
update content_bodies set title = '富士市に行くなら立ち寄りたい穴場の観光＆グルメスポット７選', description = 'この動画は静岡県への旅行を考えている方に向けて、富士市の穴場スポットを紹介しています。視聴者には、他のおすすめスポットがあればコメントでシェアするよう促しています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることがミッションで、メンバーは年間の半分を旅に費やしています。動画では、柿田川公園や大棚の滝、まかいの牧場など、具体的なスポットが紹介されています。訪れる際は、公式サイトで最新情報を確認することが推奨されています。' where id = 't9rep6ic5ItfcLKA_97W7';
update content_bodies set title = '7 Hidden Tourist and Gourmet Spots to Visit in Fuji City, Shizuoka', description = 'This video serves as a guide for those traveling to Shizuoka Prefecture, specifically highlighting hidden spots in Fuji City. It encourages viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information related to sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video details seven specific locations, including Kakita River Park, Otanada Falls, Makaino Farm, and several dining options. Viewers are advised to check official websites for the latest information before visiting.' where id = '2lyE5z-yUHSw9SlyB9KY2';
update content_bodies set title = '【高知観光/グルメ】高知に旅するなら人気グルメスポットにも行ってみたい', description = '高知県への旅行や観光に役立つ情報を提供する動画で、高知の人気グルメスポットを紹介しています。視聴者には、動画で紹介されていないおすすめのスポットをコメント欄でシェアするよう呼びかけています。このチャンネル「旅行の達人」は、観光、移動、宿泊、食事など、国内外の旅行情報を発信し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを目指し、視聴者が新しい可能性を発見できるような情報を提供しています。公式SNSアカウントをフォローし、チャンネル登録をすることで、最新情報を受け取ることができます。' where id = 'ucczlW6ZTjmqiRuBxM7DT';
update content_bodies set title = 'Kochi Tourism/Gourmet: Must-Visit Gourmet Spots in Kochi', description = 'This video serves as a guide for those traveling to Kochi Prefecture, highlighting popular gourmet spots in the area. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities and experiences. For more information and updates, viewers can follow the official social media accounts and subscribe to the channel.' where id = 'Vxkev9ctSdXOkcP8bWquE';
update content_bodies set title = '浜田の石見神楽 伝統文化体験プレミアムツアー', description = '島根県西部に位置する浜田は、日本海に面した自然豊かな街で、古くから伝わる伝統芸能が息づいています。特に石見神楽は、迫力ある奏楽と舞、豪華な衣装で人々を魅了します。浜田の人々はこの神楽の継承と発展に尽力しており、若者から高齢者までが日常生活の中で技を磨いています。このツアーでは、特別公演や地域の社中との交流、衣装や面の工房見学を通じて、浜田の人々の石見神楽への情熱を体感できます。旅の終わりには、未知の世界が広がっています。' where id = '7PHCIqW3vuf-ZR-H40k2c';
update content_bodies set title = 'Hamada Iwami Kagura Traditional Culture Experience Premium Tour', description = 'Located in the western part of Shimane Prefecture, Hamada is a city rich in nature and traditional industries facing the Sea of Japan. This area is home to traditional performing arts that have been cherished and developed over time. The powerful music and dance of Iwami Kagura, along with its stunning costumes and masks, captivate the hearts of both local residents and visitors alike. The people of Hamada have played a significant role in preserving and advancing Iwami Kagura, with young and old alike dedicating themselves to mastering these skills amidst their daily lives. This tour offers a unique opportunity to engage with special performances, interact with local groups, and visit workshops for costumes and masks, revealing the deep passion that resides in the hearts of the people of Hamada for Iwami Kagura. At the end of this extraordinary journey, a new and unknown world awaits.' where id = '7mlviVrZf82oQxoaf3YCR';
update content_bodies set title = '2019 10 釧路川源流カヌーツアー', description = '釧路川源流の澄んだ水が流れる場所で、カヌーで訪れる「鏡の間」は、湧水が沸く神秘的な空間です。この映像は、紅葉の美しい「釧路川源流と鏡の間」をドローンで撮影したものです。カヌーの申し込みは「屈斜路ecoツアーズ」さんへご連絡ください。' where id = 'b2p25VfIAku0LMm79RZrp';
update content_bodies set title = 'Kushiro River Headwaters Canoe Tour 2019', description = 'The clear waters of the Kushiro River headwaters offer a mystical space known as ''Mirror''s Room,'' where spring water bubbles up. This video captures the autumn foliage and the canoeing experience through the Kushiro River headwaters and Mirror''s Room, filmed with a drone. For canoe bookings, please contact ''Kushiro Eco Tours'' at http://kussharo-eco.com/' where id = '75G2t0DIfE7_9s4NuXqo0';
update content_bodies set title = '2016 釧路川カヌーツーリング', description = 'この動画は、釧路川でのカヌーツーリングをドローンで撮影したものです。初秋の釧路湿原と釧路川を流れるカヌーの旅をお楽しみください。' where id = 'ZgfEKnxlFFkxzsc2UYiNe';
update content_bodies set title = '2016 Kushiro River Canoeing', description = 'This is a video captured by drone showcasing a canoeing tour on the Kushiro River. Enjoy the journey of canoeing through the early autumn scenery of the Kushiro Wetlands and the Kushiro River.' where id = 'TA7exU22lGqOTVRCBA6pO';
update content_bodies set title = '栃木観光の穴場スポット', description = 'この動画は栃木県への旅行を計画している方に向けて、あまり知られていない観光スポットを紹介しています。動画で紹介されていないおすすめの場所があれば、ぜひコメント欄でシェアしてください。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。運営メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見し、旅を楽しむきっかけになればと願っています。最新情報は公式のSNSアカウントをフォローしてください。' where id = 'CH7zyQKVe4T_AWsDb_rHO';
update content_bodies set title = 'Hidden Gems in Tochigi Tourism', description = 'This video serves as a guide for those traveling to Tochigi Prefecture, highlighting lesser-known tourist spots. Viewers are encouraged to share their own recommendations in the comments if they know of any places not mentioned in the video. The channel, ''Travel Master,'' aims to provide a wealth of travel information, including sightseeing, transportation, accommodation, and dining, to enhance the travel experience. The team behind the channel believes in enriching lives through travel and hopes to inspire viewers to discover new possibilities and enjoy their journeys. For more information and updates, viewers can follow the official social media accounts.' where id = 'zE-zQIeY51kAFOnWkIkxQ';
update content_bodies set title = '古座川のゆず（和歌山県特産品）', description = '古座川のゆずは、和歌山県の特産品であり、その独特の風味と香りで知られています。この果実は、ソースやドレッシング、飲料など、さまざまな料理に使用されることが多いです。地域の気候や土壌が、ゆずの高品質に寄与しており、地元市場だけでなく国際市場でも人気のある食材となっています。詳細については、和歌山県インターネット放送局のウェブサイトをご覧ください。' where id = 'IieVqXrEyD7u_junHeOKK';
update content_bodies set title = 'Kozagawa Yuzu (Specialty of Wakayama Prefecture)', description = 'Kozagawa Yuzu is a specialty product from Wakayama Prefecture, known for its unique flavor and aroma. The fruit is often used in various culinary applications, including sauces, dressings, and beverages. The region''s climate and soil contribute to the high quality of the yuzu, making it a sought-after ingredient in both local and international markets. For more information, you can visit the Wakayama Prefecture Internet Broadcasting Station.' where id = 'X7nZFkFxioZVVsAg7ypYI';